import { T } from "../i18n";
import { ICON } from "./icons";
import { storeSnapshot, inboxCount, upcomingCount, allActiveCount, doneCount, projectTaskCount } from "../data/selectors";

/**
 * 左侧导航 · 隐式分组 · 顺序锁定（M1-New.2）
 * 导航：时间块 / 收件箱 / 即将到来 / 全部任务 / 已完成 / 数据洞察 / 周期规划
 * 项目段：从 store.projects 取，颜色用 colorToken
 */

interface NavDef {
  key: string;
  label: string;
  iconKey: keyof typeof ICON;
  count?: number;
  emphasis?: boolean;
}

export function renderSidebar(): string {
  const inboxN    = inboxCount();
  const upcomingN = upcomingCount();
  const allN      = allActiveCount();
  const doneN     = doneCount();

  const main: NavDef[] = [
    { key: "timeblock", label: T.sidebar.nav.timeblock, iconKey: "clock" },
    { key: "inbox",     label: T.sidebar.nav.inbox,     iconKey: "inbox",    count: inboxN,    emphasis: inboxN > 0 },
    { key: "upcoming",  label: T.sidebar.nav.upcoming,  iconKey: "calendar", count: upcomingN },
    { key: "allTasks",  label: T.sidebar.nav.allTasks,  iconKey: "list",     count: allN },
    { key: "completed", label: T.sidebar.nav.completed, iconKey: "check",    count: doneN },
    { key: "insight",   label: T.sidebar.nav.insight,   iconKey: "chart" },
    { key: "planning",  label: T.sidebar.nav.planning,  iconKey: "cycle" },
  ];

  const projects = storeSnapshot().projects.slice(0, 6);

  return `
    <aside class="pms-sidebar" role="navigation">
      <div class="pms-sidebar-nav-group">
        ${main.map((n) => renderNavItem(n, n.key === "timeblock")).join("")}
      </div>

      <div class="pms-sidebar-nav-group">
        <div class="pms-sidebar-group-label">${T.sidebar.sectionLabel.project}</div>
        ${projects.map((p) => `
          <div class="pms-project-list-item" data-project="${esc(p.id)}">
            <span class="pms-project-list-item-dot" style="background:var(${p.colorToken})"></span>
            <span class="pms-project-list-item-name">${esc(p.name)}</span>
            <span class="pms-project-list-item-count">${projectTaskCount(p.id)}</span>
          </div>
        `).join("")}
        ${storeSnapshot().projects.length > 6
          ? `<div class="pms-sidebar-view-all">${T.sidebar.viewAll}（共 ${storeSnapshot().projects.length} 个）</div>`
          : ""}
      </div>

      <div class="pms-sidebar-kr-card">
        <div class="pms-sidebar-kr-card-title">${T.sidebar.sectionLabel.kr}</div>
        <div class="pms-sidebar-kr-card-body">
          本期重点：让 M1-New 骨架接入真实数据，跑通最小 CRUD。
        </div>
      </div>
    </aside>
  `;
}

function renderNavItem(n: NavDef, active: boolean): string {
  const cntClass = n.emphasis ? "pms-sidebar-nav-item-count is-emphasis" : "pms-sidebar-nav-item-count";
  return `
    <div class="pms-sidebar-nav-item${active ? " is-active" : ""}" data-nav="${esc(n.key)}">
      <span class="pms-sidebar-nav-item-icon">${ICON[n.iconKey]}</span>
      <span class="pms-sidebar-nav-item-label">${esc(n.label)}</span>
      ${typeof n.count === "number" ? `<span class="${cntClass}">${n.count}</span>` : ""}
    </div>
  `;
}

function esc(s: string): string {
  return (s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
}
