/**
 * 无限进步 M1-New.2 · 入口
 *
 * 启动序列：
 *   1. tokens.css 由 vite 处理 link 标签
 *   2. injectStyles 注入组件 CSS
 *   3. loadStore 从 localStorage 加载（key=wuxianjinbu-data-v1），空则写入 seed
 *   4. initAppShell 编排 4 区 + 抽屉 + 事件委托
 *
 * 严格不读旧 cadence-data-lishan-v4 / 不调 /api/* / 不注册 SW。
 */

import { injectStyles } from "./styles";
import { loadStore } from "./data/storage";
import { initAppShell } from "./appShell";

function bootstrap(): void {
  injectStyles();
  loadStore();          // 触发首次加载 + seed
  initAppShell();

  if (typeof window !== "undefined") {
    console.info(
      "%c无限进步 · M1-New.2",
      "color:#2B54C9;font-weight:600;font-size:13px",
      "· localStorage: wuxianjinbu-data-v1· schema v1 · 无 /api 无 SW",
    );
  }
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", bootstrap);
} else {
  bootstrap();
}
