/**
 * 右侧信息栏 · M1-New.3R
 *
 * 模块顺序（v0.2.1）：
 * 1. 快速捕捉
 * 2. 当前进行
 * 3. 今日进度（时间块完成数/总数）
 * 4. 周期事项占位
 * 5. AI 建议占位
 */

import { T } from "../i18n";
import { runningBlockForDay, todayProgress } from "../data/selectors";
import { findTask } from "../data/actions";
import { localDateKey } from "../data/types";
import { fmtTime } from "../lib/timeUtils";
import { getViewDate } from "./timeline";

export function renderRightSidebar(): string {
  const viewDate = getViewDate();
  return `
<aside class="pms-right-sidebar" role="complementary">
  ${renderQuickCapture()}
  ${renderCurrentRunning(viewDate)}
  ${renderTodayProgress(viewDate)}
  ${renderPeriodicPlaceholder()}
  ${renderAiSlot()}
</aside>`;
}

function renderQuickCapture(): string {
  return `
<div class="rps">
  <div class="rps-title">${esc(T.right.sectionCapture)}</div>
  <div class="qc-wrap">
    <span class="qc-plus">+</span>
    <input type="text" id="pms-quick-capture"
      class="qc-input"
      placeholder="${esc(T.right.capturePlaceholder)}"
      autocomplete="off" />
    <span class="qc-kbd">&#8984;K</span>
  </div>
</div>`;
}

function renderCurrentRunning(viewDate: string): string {
  const tb = runningBlockForDay(viewDate);
  if (!tb) {
    return `<div class="rps">
      <div class="rps-title">${esc(T.right.sectionRunning)}</div>
      <div class="rps-empty">${esc(T.right.none)}</div>
    </div>`;
  }
  const task = tb.taskId ? findTask(tb.taskId) : null;
  const title = task ? task.title : tb.title;
  const elapsed = _elapsedLabel(tb.start);
  return `
<div class="rps">
  <div class="rps-title">${esc(T.right.sectionRunning)}</div>
  <div class="inprog-card">
    <div class="inprog-lbl">进行中</div>
    <div class="inprog-title">${esc(title)}</div>
    <div class="inprog-time">${esc(fmtTime(tb.start))} — ${esc(fmtTime(tb.end))} · ${esc(elapsed)}</div>
  </div>
</div>`;
}

function renderTodayProgress(viewDate: string): string {
  const today = localDateKey();
  const isToday = viewDate === today;
  const prog = todayProgress(viewDate);
  const circ = 2 * Math.PI * 22;
  const dash = circ * (prog.pct / 100);
  const desc = prog.total === 0
    ? "今日暂无时间块"
    : `已完成 ${prog.done} / ${prog.total} 个时间块`;

  return `
<div class="rps">
  <div class="rps-title">${esc(isToday ? T.right.sectionProgress : "本日进度")}</div>
  <div class="pms-today-progress">
    <svg class="pms-today-progress-ring" viewBox="0 0 56 56">
      <circle cx="28" cy="28" r="22" fill="none" stroke="var(--bg-2)" stroke-width="5"/>
      <circle cx="28" cy="28" r="22" fill="none"
              stroke="var(--accent)" stroke-width="5"
              stroke-dasharray="${dash.toFixed(1)} ${circ.toFixed(1)}"
              transform="rotate(-90 28 28)" stroke-linecap="round"/>
    </svg>
    <div class="pms-today-progress-text">
      <div class="pms-progress-ratio pms-numeric">${prog.done} / ${prog.total}</div>
      <div class="pms-progress-label">${esc(desc)}</div>
    </div>
  </div>
</div>`;
}

function renderPeriodicPlaceholder(): string {
  return `
<div class="rps">
  <div class="rps-title">${esc(T.right.sectionPeriodic)}</div>
  <div class="rps-empty" style="font-size:11px;color:var(--text-4)">周期事项 M1-New.3A 上线</div>
</div>`;
}

function renderAiSlot(): string {
  return `
<div class="rps">
  <div class="rps-title">${esc(T.right.sectionAi)}</div>
  <div class="ai-slot">
    <div class="ai-slot-icon">
      <svg width="10" height="10" viewBox="0 0 10 10" fill="none">
        <path d="M5 1L6.2 3.9H9.5L6.8 5.9 7.7 9 5 7.2 2.3 9 3.2 5.9.5 3.9H3.8L5 1Z"
              fill="var(--accent)" opacity=".8"/>
      </svg>
    </div>
    <div class="ai-slot-title">秘书式 AI 建议</div>
    <div class="ai-slot-sub">${esc(T.right.aiNotConfigured)}</div>
    <div class="ai-slot-btn" data-act="open-ai-schedule">${esc(T.right.aiConfigBtn)}</div>
  </div>
</div>`;
}

function _elapsedLabel(startIso: string): string {
  const mins = Math.max(0, Math.floor((Date.now() - new Date(startIso).getTime()) / 60000));
  if (mins < 60) return `已用 ${mins} 分钟`;
  return `已用 ${Math.floor(mins / 60)} 小时 ${mins % 60} 分钟`;
}

function esc(s: string): string {
  return (s ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!,
  );
}
