/**
 * 本地启发式排程引擎 · M1-New.3R
 *
 * 在无 AI API 时，用规则生成日程草案：
 * 1. 按优先级 P1>P2>P3>P4 排序
 * 2. dueDate 越近越靠前
 * 3. 逾期任务优先
 * 4. AI 预估工时作为时长；缺失则默认 60min
 * 5. 在用户可用时间段内找空档（避开已有时间块）
 * 6. 生成草案 ScheduleDraftItem[]，不直接写入 localStorage
 */

import type { WjbTask } from "../data/types";
import { localDateKey } from "../data/types";
import { blocksForDay } from "../data/selectors";
import { composeDatetime, minutesToHhmm, snapMinutes } from "./timeUtils";

export interface ScheduleDraftItem {
  id: string;
  title: string;
  sourceType: "task" | "manual" | "ai_draft";
  taskId?: string;
  start: string;   // ISO datetime
  end: string;     // ISO datetime
  reason?: string; // AI / 规则说明
}

export interface ScheduleOptions {
  dateKey: string;          // 安排哪天
  availStart: number;       // 可用起始分钟（如 7*60=420）
  availEnd: number;         // 可用结束分钟（如 23*60=1380）
  selectedTasks: WjbTask[]; // 用户选择的任务列表
  skipBlocks?: string[];    // 忽略的已有时间块 id（用户取消勾选的）
}

/**
 * 生成本地日程草案
 */
export function runLocalSchedule(opts: ScheduleOptions): ScheduleDraftItem[] {
  const { dateKey, availStart, availEnd, selectedTasks, skipBlocks = [] } = opts;
  const today = localDateKey();

  // 已有时间块占用（跳过用户取消的）
  const existingBlocks = blocksForDay(dateKey).filter(
    (b) => !skipBlocks.includes(b.id),
  );

  // 已占用时段 [startMins, endMins]
  const occupied: [number, number][] = existingBlocks.map((b) => {
    const sd = new Date(b.start);
    const ed = new Date(b.end);
    const ds = new Date(dateKey + "T00:00:00");
    const startMins = Math.floor((sd.getTime() - ds.getTime()) / 60000);
    const endMins = Math.floor((ed.getTime() - ds.getTime()) / 60000);
    return [Math.max(0, startMins), Math.min(24 * 60, endMins)];
  });

  // 按优先级 + 逾期 + dueDate 近度排序
  const sorted = [...selectedTasks].sort((a, b) => {
    const priOrder = { P1: 0, P2: 1, P3: 2, P4: 3 };
    const aOverdue = a.dueDate && a.dueDate < today ? -100 : 0;
    const bOverdue = b.dueDate && b.dueDate < today ? -100 : 0;
    const aDue = a.dueDate ? new Date(a.dueDate).getTime() : Number.MAX_SAFE_INTEGER;
    const bDue = b.dueDate ? new Date(b.dueDate).getTime() : Number.MAX_SAFE_INTEGER;
    const priDiff = priOrder[a.priority] - priOrder[b.priority];
    if (aOverdue !== bOverdue) return aOverdue - bOverdue;
    if (priDiff !== 0) return priDiff;
    return aDue - bDue;
  });

  let cursor = availStart; // 当前可安排位置（分钟）
  const result: ScheduleDraftItem[] = [];

  for (const task of sorted) {
    const dur = task.aiEstimatedMinutes ?? 60;
    const snap = 15;

    // 找到 cursor 之后第一个可用槽
    let slotStart = snapMinutes(cursor, snap);
    let slotEnd = slotStart + dur;

    // 跳过被占用的时段
    let attempts = 0;
    while (attempts < 100) {
      const conflict = occupied.find(([os, oe]) => oe > slotStart && os < slotEnd);
      if (!conflict) break;
      slotStart = snapMinutes(conflict[1] + 5, snap);
      slotEnd = slotStart + dur;
      attempts++;
    }

    if (slotEnd > availEnd) break; // 超出可用时间，停止排程

    const startIso = composeDatetime(dateKey, minutesToHhmm(slotStart));
    const endIso = composeDatetime(dateKey, minutesToHhmm(slotEnd));

    result.push({
      id: `draft_${task.id}_${Date.now()}`,
      title: task.title,
      sourceType: "task",
      taskId: task.id,
      start: startIso,
      end: endIso,
      reason: _priorityReason(task, today),
    });

    // 把已排槽加入占用
    occupied.push([slotStart, slotEnd]);
    cursor = slotEnd + 5; // 5 分钟缓冲
  }

  return result;
}

function _priorityReason(task: WjbTask, today: string): string {
  if (task.dueDate && task.dueDate < today) return `逾期任务 · ${task.priority}`;
  if (task.dueDate === today) return `今日截止 · ${task.priority}`;
  if (task.priority === "P1") return "紧急优先级";
  if (task.priority === "P2") return "高优先级";
  return task.priority;
}
