import { T } from "../i18n";
import { ICON, LOGO_ICON } from "./icons";

/**
 * 顶部栏 · .pms-topbar
 * 区域：品牌（左 224px）| 搜索（中，居中最大 420px）| 工具区（右：开发日志 / 设置）
 * 不常驻数据状态；正常运行不打扰。
 */
export function renderTopbar(): string {
  return `
    <header class="pms-topbar" role="banner">
      <div class="pms-brand-bar">
        <div class="pms-brand-bar-mark">${LOGO_ICON}</div>
        <div class="pms-brand-bar-name">${T.brand.name}</div>
      </div>

      <div class="pms-global-search">
        <span class="pms-global-search-icon">${ICON.search}</span>
        <input
          id="pms-global-search-input"
          class="pms-global-search-input"
          type="text"
          placeholder="${T.topbar.searchPlaceholder}"
          autocomplete="off"
        />
        <span class="pms-global-search-kbd" aria-hidden="true">⌘K</span>
      </div>

      <div class="pms-topbar-tools">
        <button class="pms-topbar-tool-button" data-act="open-changelog" type="button">
          ${ICON.changelog}<span>${T.topbar.devLog}</span>
        </button>
        <button class="pms-topbar-tool-button" data-act="open-settings" type="button">
          ${ICON.settings}<span>${T.topbar.settings}</span>
        </button>
      </div>
    </header>
  `;
}
