/**
 * 「安排日程」AI 访谈卡片 · M1-New.3R
 *
 * 8 页选择题式流程，不是聊天机器人。
 * 本轮使用本地模拟排程引擎（不接真实 API）。
 * 结构化草案生成后，用户确认后写入时间轴（createTimeBlock）。
 */

import { T } from "../i18n";
import { allActiveTasks } from "../data/selectors";
import { blocksForDay } from "../data/selectors";
import { createTimeBlock } from "../data/actions";
import { localDateKey } from "../data/types";
import { addDays, friendlyDate } from "../lib/timeUtils";
import { runLocalSchedule, type ScheduleDraftItem } from "../lib/localScheduler";
import type { WjbTask } from "../data/types";

const CARD_ID = "pms-ai-schedule-card";
const SCRIM_ID = "pms-ai-schedule-scrim";

/* ── 状态机 ─────────────────────────────────────────────── */

type AiCardState =
  | { phase: "unconfigured" }
  | { phase: "interview"; page: number; data: InterviewData }
  | { phase: "loading" }
  | { phase: "error"; errMsg: string }
  | { phase: "draft"; items: ScheduleDraftItem[]; data: InterviewData }
  | { phase: "applied" };

interface InterviewData {
  dateKey: string;
  availStart: number;  // 分钟
  availEnd: number;
  fixedBlockIds: string[];       // page3：选中保留的已有时间块
  selectedTaskIds: string[];     // page4：用户选择的任务
  skippedTaskIds: string[];      // page5：暂不安排
}

let _state: AiCardState = { phase: "unconfigured" };
let _afterApply: (() => void) | null = null;

export function setAiCardAfterApply(cb: () => void): void { _afterApply = cb; }

/* ── 打开 / 关闭 ─────────────────────────────────────────── */

export function openAiScheduleCard(): void {
  closeAiScheduleCard();

  const today = localDateKey();
  _state = {
    phase: "interview",
    page: 1,
    data: {
      dateKey: today,
      availStart: 7 * 60,
      availEnd: 23 * 60,
      fixedBlockIds: [],
      selectedTaskIds: [],
      skippedTaskIds: [],
    },
  };

  _mount();
}

export function closeAiScheduleCard(): void {
  document.getElementById(CARD_ID)?.remove();
  document.getElementById(SCRIM_ID)?.remove();
}

function _mount(): void {
  const scrim = document.createElement("div");
  scrim.id = SCRIM_ID;
  scrim.className = "ai-card-scrim";
  scrim.setAttribute("data-act", "close-ai-schedule");
  document.body.appendChild(scrim);

  const card = document.createElement("div");
  card.id = CARD_ID;
  card.className = "ai-card-wrap";
  card.innerHTML = _buildHtml();
  document.body.appendChild(card);
}

function _repaint(): void {
  const card = document.getElementById(CARD_ID);
  if (card) card.innerHTML = _buildHtml();
}

/* ── HTML 构建 ───────────────────────────────────────────── */

function _buildHtml(): string {
  switch (_state.phase) {
    case "unconfigured": return _buildUnconfigured();
    case "interview":    return _buildInterview(_state.page, _state.data);
    case "loading":      return _buildLoading();
    case "error":        return _buildError(_state.errMsg);
    case "draft":        return _buildDraft(_state.items, _state.data);
    case "applied":      return _buildApplied();
  }
}

function _buildHeader(page: number, total = 8): string {
  const dots = Array.from({ length: total }, (_, i) => {
    const cls = i < page - 1 ? "ai-prog-done" : i === page - 1 ? "ai-prog-active" : "ai-prog-empty";
    return `<div class="${cls}"></div>`;
  }).join("");
  return `
<div class="ai-card-top">
  <div class="ai-card-logo">
    <svg width="12" height="12" viewBox="0 0 10 10" fill="none">
      <path d="M5 1L6.2 3.9H9.5L6.8 5.9 7.7 9 5 7.2 2.3 9 3.2 5.9.5 3.9H3.8L5 1Z"
            fill="white" opacity=".9"/>
    </svg>
  </div>
  <div class="ai-card-lbl">${esc(T.ai.arrange.cardTitle)}</div>
  <div class="ai-prog">${dots}</div>
  <button class="ai-card-close" data-act="close-ai-schedule" type="button">&#x2715;</button>
</div>`;
}

function _buildFooter(_page: number, showPrev: boolean, nextLabel?: string): string {
  return `
<div class="ai-card-footer">
  <button class="ai-skip-btn" data-act="close-ai-schedule" type="button">${esc(T.ai.arrange.cancelBtn)}</button>
  <div style="flex:1"></div>
  ${showPrev ? `<button class="ai-prev-btn" data-act="ai-prev" type="button">${esc(T.ai.arrange.prevBtn)}</button>` : ""}
  <button class="ai-next-btn" data-act="ai-next" type="button">
    ${esc(nextLabel ?? T.ai.arrange.nextBtn)} ›
  </button>
</div>`;
}

function _buildUnconfigured(): string {
  return `
${_buildHeader(1)}
<div class="ai-card-body ai-state-body">
  <div class="ai-state-icon unconfigured">
    <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
      <circle cx="10" cy="10" r="8" stroke="var(--text-3)" stroke-width="1.5"/>
      <path d="M10 6v5" stroke="var(--text-3)" stroke-width="1.5" stroke-linecap="round"/>
      <circle cx="10" cy="14" r="1" fill="var(--text-3)"/>
    </svg>
  </div>
  <div class="ai-state-title">${esc(T.ai.arrange.unconfiguredTitle)}</div>
  <div class="ai-state-desc">${esc(T.ai.arrange.unconfiguredDesc)}</div>
  <div class="ai-state-actions">
    <button class="ai-action-btn is-primary" data-act="ai-use-mock" type="button">
      ${esc(T.ai.arrange.mockBtn)}
    </button>
    <button class="ai-action-btn is-sec" data-act="close-ai-schedule" type="button">
      ${esc(T.ai.arrange.cancelBtn)}
    </button>
  </div>
</div>`;
}

function _buildLoading(): string {
  return `
${_buildHeader(6, 6)}
<div class="ai-card-body ai-state-body">
  <div class="ai-state-icon loading">
    <svg width="20" height="20" viewBox="0 0 10 10" fill="none">
      <path d="M5 1L6.2 3.9H9.5L6.8 5.9 7.7 9 5 7.2 2.3 9 3.2 5.9.5 3.9H3.8L5 1Z"
            fill="var(--accent)" opacity=".8"/>
    </svg>
  </div>
  <div class="ai-state-title">${esc(T.ai.arrange.loadingTitle)}</div>
  <div class="ai-loading-dots">
    <div class="ai-dot"></div><div class="ai-dot"></div><div class="ai-dot"></div>
  </div>
</div>`;
}

function _buildError(msg: string): string {
  return `
${_buildHeader(6)}
<div class="ai-card-body ai-state-body">
  <div class="ai-state-icon error">
    <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
      <circle cx="10" cy="10" r="8" stroke="var(--danger)" stroke-width="1.5"/>
      <path d="M10 6v5M10 14v.5" stroke="var(--danger)" stroke-width="1.5" stroke-linecap="round"/>
    </svg>
  </div>
  <div class="ai-state-title">${esc(T.ai.arrange.errorTitle)}</div>
  <div class="ai-state-desc">${esc(msg || T.ai.arrange.errorDesc)}</div>
  <div class="ai-state-actions">
    <button class="ai-action-btn is-primary" data-act="ai-use-mock" type="button">${esc(T.ai.arrange.mockBtn)}</button>
    <button class="ai-action-btn is-sec" data-act="close-ai-schedule" type="button">${esc(T.ai.arrange.cancelBtn)}</button>
  </div>
</div>`;
}

function _buildInterview(page: number, data: InterviewData): string {
  const today = localDateKey();
  switch (page) {
    case 1: return _buildPage1(data, today);
    case 2: return _buildPage2(data);
    case 3: return _buildPage3(data);
    case 4: return _buildPage4(data, today);
    case 5: return _buildPage5(data, today);
    default: return _buildPage1(data, today);
  }
}

function _buildPage1(data: InterviewData, today: string): string {
  const options = [
    { k: today, l: T.ai.arrange.pages.p1Today },
    { k: addDays(today, 1), l: T.ai.arrange.pages.p1Tomorrow },
    { k: addDays(today, 2), l: T.ai.arrange.pages.p1Dayafter },
  ];
  return `
${_buildHeader(1)}
<div class="ai-card-body">
  <div class="ai-question">${esc(T.ai.arrange.pages.p1Title)}</div>
  <div class="ai-options">
    ${options.map((o) => `
      <button class="ai-option${data.dateKey === o.k ? " is-selected" : ""}"
        data-act="ai-p1-date" data-value="${esc(o.k)}" type="button">
        <div class="ai-opt-icon"></div>
        ${esc(o.l)}
      </button>`).join("")}
    <button class="ai-option" data-act="ai-p1-custom" type="button">
      <div class="ai-opt-icon"></div>
      ${esc(T.ai.arrange.pages.p1Custom)} →
    </button>
  </div>
</div>
${_buildFooter(1, false)}`;
}

function _buildPage2(data: InterviewData): string {
  const presets = [
    { start: 7*60, end: 23*60, l: T.ai.arrange.pages.p2Default },
    { start: 8*60, end: 23*60, l: T.ai.arrange.pages.p2Late },
    { start: 7*60, end: 22*60, l: T.ai.arrange.pages.p2Early },
  ];
  return `
${_buildHeader(2)}
<div class="ai-card-body">
  <div class="ai-question">${esc(T.ai.arrange.pages.p2Title)}</div>
  <div class="ai-options">
    ${presets.map((p) => `
      <button class="ai-option${data.availStart === p.start && data.availEnd === p.end ? " is-selected" : ""}"
        data-act="ai-p2-avail" data-start="${p.start}" data-end="${p.end}" type="button">
        <div class="ai-opt-icon"></div>
        ${esc(p.l)}
      </button>`).join("")}
  </div>
</div>
${_buildFooter(2, true)}`;
}

function _buildPage3(data: InterviewData): string {
  const dateKey = data.dateKey;
  const blocks = blocksForDay(dateKey);
  return `
${_buildHeader(3)}
<div class="ai-card-body">
  <div class="ai-question">${esc(T.ai.arrange.pages.p3Title)}</div>
  <div class="ai-hint-text">${esc(T.ai.arrange.pages.p3Hint)}</div>
  ${blocks.length === 0
    ? `<div class="ai-empty-hint">今天暂无已有安排，AI 会从空白开始规划。</div>`
    : `<div class="ai-task-list">
        ${blocks.map((b) => {
          const checked = !data.fixedBlockIds.includes(b.id) || data.fixedBlockIds.length === 0;
          return `<div class="ai-task-row${checked ? " is-selected" : ""}"
            data-act="ai-p3-toggle" data-block-id="${esc(b.id)}">
            <div class="ai-check">${checked ? "✓" : ""}</div>
            <div style="flex:1;font-size:12.5px;font-weight:600">${esc(b.title)}</div>
            <div style="font-size:10.5px;color:var(--text-4)">${_fmtMins(new Date(b.start).getHours()*60+new Date(b.start).getMinutes())} — ${_fmtMins(new Date(b.end).getHours()*60+new Date(b.end).getMinutes())}</div>
          </div>`;
        }).join("")}
      </div>`
  }
</div>
${_buildFooter(3, true)}`;
}

function _buildPage4(data: InterviewData, today: string): string {
  const tasks = allActiveTasks()
    .filter((t) => t.status !== "done")
    .sort((a, b) => {
      const po = { P1: 0, P2: 1, P3: 2, P4: 3 };
      const ao = a.dueDate && a.dueDate < today ? -100 : 0;
      const bo = b.dueDate && b.dueDate < today ? -100 : 0;
      if (ao !== bo) return ao - bo;
      return po[a.priority] - po[b.priority];
    })
    .slice(0, 10);

  return `
${_buildHeader(4)}
<div class="ai-card-body">
  <div class="ai-question">${esc(T.ai.arrange.pages.p4Title)}</div>
  <div class="ai-hint-text">${esc(T.ai.arrange.pages.p4Hint)}</div>
  <div class="ai-task-list">
    ${tasks.map((t) => {
      const isSel = data.selectedTaskIds.includes(t.id);
      return `<div class="ai-task-row${isSel ? " is-selected" : ""}"
        data-act="ai-p4-toggle" data-task-id="${esc(t.id)}">
        <div class="ai-check">${isSel ? "✓" : ""}</div>
        <div class="ai-pri-dot" style="background:${_priColor(t.priority)}"></div>
        <div class="ai-task-title">${esc(t.title)}</div>
        <div class="ai-task-est">${t.aiEstimatedMinutes ? _durationShort(t.aiEstimatedMinutes) : ""}</div>
      </div>`;
    }).join("")}
  </div>
</div>
${_buildFooter(4, true)}`;
}

function _buildPage5(data: InterviewData, today: string): string {
  const notSelected = allActiveTasks()
    .filter((t) => t.status !== "done" && !data.selectedTaskIds.includes(t.id))
    .slice(0, 8);

  return `
${_buildHeader(5)}
<div class="ai-card-body">
  <div class="ai-question">${esc(T.ai.arrange.pages.p5Title)}</div>
  ${notSelected.length === 0
    ? `<div class="ai-empty-hint">所有任务均已选入，无需确认暂不安排。</div>`
    : `<div class="ai-task-list">
        ${notSelected.map((t) => {
          const isSkip = data.skippedTaskIds.includes(t.id);
          return `<div class="ai-task-row${isSkip ? " is-selected" : ""}"
            data-act="ai-p5-toggle" data-task-id="${esc(t.id)}">
            <div class="ai-check">${isSkip ? "✓" : ""}</div>
            <div class="ai-task-title">${esc(t.title)}</div>
            <div class="ai-task-est">${t.dueDate && t.dueDate < today ? "逾期" : (t.priority)}</div>
          </div>`;
        }).join("")}
      </div>`
  }
</div>
${_buildFooter(5, true, T.ai.arrange.nextBtn + " · 生成草案")}`;
}

function _buildDraft(items: ScheduleDraftItem[], data: InterviewData): string {
  const today = localDateKey();
  const dateTxt = friendlyDate(data.dateKey, today);

  const draftRows = items.map((item) => `
<div class="ai-draft-row">
  <div class="ai-draft-time">${_fmtIso(item.start)} — ${_fmtIso(item.end)}</div>
  <div class="ai-draft-strip ${item.sourceType}"></div>
  <div class="ai-draft-body">
    <div class="ai-draft-title">${esc(item.title)}</div>
    ${item.reason ? `<div class="ai-draft-reason">${esc(item.reason)}</div>` : ""}
  </div>
</div>`).join("");

  return `
${_buildHeader(6)}
<div class="ai-card-body">
  <div class="ai-question">${esc(T.ai.arrange.pages.p6Title)}</div>
  ${items.length === 0
    ? `<div class="ai-empty-hint">可用时间不足以安排所有任务，请尝试调整可用时间段。</div>`
    : `<div class="ai-draft-list">${draftRows}</div>`
  }
</div>
<div class="ai-card-footer">
  <button class="ai-skip-btn" data-act="close-ai-schedule" type="button">${esc(T.ai.arrange.cancelBtn)}</button>
  <div style="flex:1"></div>
  <button class="ai-prev-btn" data-act="ai-regen" type="button">${esc(T.ai.arrange.regenerateBtn)}</button>
  <button class="ai-next-btn" data-act="ai-apply" type="button">
    ${esc(T.ai.arrange.applyBtn)} · ${esc(dateTxt)} (${items.length}个)
  </button>
</div>`;
}

function _buildApplied(): string {
  return `
${_buildHeader(8)}
<div class="ai-card-body ai-state-body">
  <div class="ai-state-icon success" style="background:var(--success-soft)">
    <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
      <circle cx="10" cy="10" r="8" stroke="var(--success)" stroke-width="1.5"/>
      <path d="M6.5 10l2.5 2.5 4.5-4.5" stroke="var(--success)" stroke-width="1.5" stroke-linecap="round"/>
    </svg>
  </div>
  <div class="ai-state-title">日程已应用到时间轴</div>
  <div class="ai-state-desc">时间块已生成，快去查看今天的安排吧。</div>
  <div class="ai-state-actions">
    <button class="ai-action-btn is-primary" data-act="close-ai-schedule" type="button">好的</button>
  </div>
</div>`;
}

/* ── 事件处理（appShell 根委托调用）──────────────────────── */

export function handleAiCardClick(act: string, target: HTMLElement): void {
  switch (act) {
    case "close-ai-schedule":
      closeAiScheduleCard(); return;

    case "ai-use-mock":
      _state = { phase: "interview", page: 1, data: {
        dateKey: localDateKey(), availStart: 7*60, availEnd: 23*60,
        fixedBlockIds: [], selectedTaskIds: [], skippedTaskIds: [],
      }};
      _repaint(); return;

    case "ai-prev":
      if (_state.phase === "interview" && _state.page > 1) {
        _state.page -= 1; _repaint();
      } return;

    case "ai-next":
      if (_state.phase === "interview") {
        if (_state.page < 5) { _state.page += 1; _repaint(); }
        else _generateDraft();
      } return;

    case "ai-regen":
      if (_state.phase === "draft") _generateDraft(); return;

    case "ai-apply":
      if (_state.phase === "draft") _applyDraft(_state.items); return;

    case "ai-p1-date": {
      const d = target.dataset.value;
      if (d && _state.phase === "interview") { _state.data.dateKey = d; _repaint(); } return;
    }

    case "ai-p2-avail": {
      const s = Number(target.dataset.start);
      const e = Number(target.dataset.end);
      if (_state.phase === "interview") { _state.data.availStart = s; _state.data.availEnd = e; _repaint(); } return;
    }

    case "ai-p3-toggle": {
      const id = target.dataset.blockId;
      if (!id || _state.phase !== "interview") return;
      const ids = _state.data.fixedBlockIds;
      const idx = ids.indexOf(id);
      if (idx === -1) ids.push(id); else ids.splice(idx, 1);
      _repaint(); return;
    }

    case "ai-p4-toggle": {
      const id = target.dataset.taskId;
      if (!id || _state.phase !== "interview") return;
      const ids = _state.data.selectedTaskIds;
      const idx = ids.indexOf(id);
      if (idx === -1) {
        if (ids.length < 6) ids.push(id);
      } else ids.splice(idx, 1);
      _repaint(); return;
    }

    case "ai-p5-toggle": {
      const id = target.dataset.taskId;
      if (!id || _state.phase !== "interview") return;
      const ids = _state.data.skippedTaskIds;
      const idx = ids.indexOf(id);
      if (idx === -1) ids.push(id); else ids.splice(idx, 1);
      _repaint(); return;
    }
  }
}

function _generateDraft(): void {
  if (_state.phase !== "interview" && _state.phase !== "draft") return;
  const data = _state.phase === "interview" ? _state.data : _state.data;

  // 模拟"加载中"状态（立即调用本地排程）
  const savedData = data;
  _state = { phase: "loading" };
  _repaint();

  setTimeout(() => {
    const allTasks = allActiveTasks();
    const selectedTasks = allTasks.filter((t) => savedData.selectedTaskIds.includes(t.id));
    const skipBlocks = blocksForDay(savedData.dateKey)
      .filter((b) => savedData.fixedBlockIds.includes(b.id))
      .map((b) => b.id);

    const items = runLocalSchedule({
      dateKey: savedData.dateKey,
      availStart: savedData.availStart,
      availEnd: savedData.availEnd,
      selectedTasks,
      skipBlocks,
    });

    _state = { phase: "draft", items, data: savedData };
    _repaint();
  }, 800); // 假装思考 0.8 秒
}

function _applyDraft(items: ScheduleDraftItem[]): void {
  for (const item of items) {
    createTimeBlock({
      title: item.title,
      start: item.start,
      end: item.end,
      taskId: item.taskId,
      source: item.taskId ? "task" : "ai_draft",
    });
  }
  _state = { phase: "applied" };
  _repaint();
  _afterApply?.();
}

/* ── 辅助 ────────────────────────────────────────────────── */

function _fmtMins(mins: number): string {
  return `${String(Math.floor(mins / 60)).padStart(2, "0")}:${String(mins % 60).padStart(2, "0")}`;
}

function _fmtIso(iso: string): string {
  const d = new Date(iso);
  return _fmtMins(d.getHours() * 60 + d.getMinutes());
}

function _durationShort(mins: number): string {
  if (mins < 60) return `${mins}分`;
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return m === 0 ? `${h}h` : `${h}h${m}分`;
}

function _priColor(p: WjbTask["priority"]): string {
  return { P1: "var(--danger)", P2: "var(--warning)", P3: "var(--text-4)", P4: "var(--text-4)" }[p];
}

function esc(s: string): string {
  return (s ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!,
  );
}
