/**
 * 0–24 像素定位时间轴 · M1-New.3R
 *
 * 核心改变（对比旧 stage.ts 的小时分组）：
 * - 单一 position:relative 容器，所有时间块 position:absolute
 * - top = startMinutes / 60 * HOUR_H
 * - height = durationMinutes / 60 * HOUR_H
 * - hourHeight = 64px（固定）
 * - 跨日：渲染当天切片
 * - 支持日期导航（viewDate）
 *
 * 状态卡片内联操作：
 * - 待办 hover → 「开始」按钮
 * - 进行中 hover → 「完成」按钮
 * - 已完成 hover → 「复盘」按钮
 */

import { T } from "../i18n";
import type { WjbTimeBlock } from "../data/types";
import { blocksForDay, todayProgress } from "../data/selectors";
import { findTask } from "../data/actions";
import { localDateKey } from "../data/types";
import {
  minutesFromDayStart,
  blockDurationMinutes,
  crossDayState,
  fmtTime,
  currentMinuteOffset,
  addDays,
} from "../lib/timeUtils";

export const HOUR_H = 64; // px per hour，和视觉稿一致

/* ── 全局视图日期（日期导航状态）─────────────────────────── */
let _viewDate: string = localDateKey();

export function getViewDate(): string { return _viewDate; }

export function setViewDate(d: string): void {
  _viewDate = d;
}

export function goToToday(): void {
  _viewDate = localDateKey();
}

export function goNextDay(): void {
  _viewDate = addDays(_viewDate, 1);
}

export function goPrevDay(): void {
  _viewDate = addDays(_viewDate, -1);
}

/* ── 主渲染 ──────────────────────────────────────────────── */

export function renderTimeline(): string {
  const dateKey = _viewDate;
  const today = localDateKey();
  const isToday = dateKey === today;
  const blocks = blocksForDay(dateKey);
  const prog = todayProgress(dateKey);

  // 日期标题
  const d = new Date(dateKey + "T12:00:00");
  const wds = ["日", "一", "二", "三", "四", "五", "六"];
  const dateLabel = `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;
  const wdLabel = `周${wds[d.getDay()]}`;

  const blockCountInfo = blocks.length > 0
    ? T.timeline.blockCountTpl(blocks.length, prog.done)
    : T.timeline.noBlocksToday;

  return `
<div class="tl-container">
  <!-- Header -->
  <div class="tl-header">
    <div class="tl-header-row1">
      <div class="tl-date-nav">
        <button class="tl-nav-btn" data-act="tl-prev-day" title="${esc(T.timeline.prevDay)}" type="button">&#8249;</button>
        <button class="tl-today-btn" data-act="tl-today" type="button">${esc(T.timeline.today)}</button>
        <button class="tl-nav-btn" data-act="tl-next-day" title="${esc(T.timeline.nextDay)}" type="button">&#8250;</button>
      </div>
      <div class="tl-date-label"
           data-act="tl-open-date-picker"
           title="点击选择日期">${esc(dateLabel)}</div>
      <div class="tl-weekday-label">${esc(wdLabel)}</div>
      ${isToday ? `<div class="tl-today-badge">今天</div>` : ""}
      <div style="flex:1"></div>
      <div class="tl-view-toggle">
        <button class="tl-view-btn is-active" type="button">${esc(T.timeline.dayView)}</button>
        <button class="tl-view-btn is-disabled" type="button" title="${esc(T.timeline.comingSoon)}">
          ${esc(T.timeline.weekView)}
        </button>
        <button class="tl-view-btn is-disabled" type="button" title="${esc(T.timeline.comingSoon)}">
          ${esc(T.timeline.monthView)}
        </button>
      </div>
      <button class="tl-arrange-btn" data-act="open-ai-schedule" type="button">
        <svg width="14" height="14" viewBox="0 0 10 10" fill="none" class="tl-arrange-icon">
          <path d="M5 1L6.2 3.9H9.5L6.8 5.9 7.7 9 5 7.2 2.3 9 3.2 5.9.5 3.9H3.8L5 1Z"
                fill="rgba(255,255,255,.85)"/>
        </svg>
        ${esc(T.timeline.arrangeBtn)}
      </button>
    </div>
    <div class="tl-header-row2">${esc(blockCountInfo)}</div>
  </div>

  <!-- Timeline body -->
  <div class="tl-scroll-wrap" id="pms-tl-scroll">
    ${renderTimelineBody(blocks, dateKey, isToday)}
    <button class="tl-add-btn" data-act="add-timeblock" type="button">
      + ${esc(T.timeline.addBtn)}
    </button>
  </div>
</div>`;
}

function renderTimelineBody(blocks: WjbTimeBlock[], dateKey: string, isToday: boolean): string {
  // 小时刻度
  const hoursHtml = Array.from({ length: 25 }, (_, h) => {
    const topPx = h * HOUR_H;
    return `
      <div class="tl-hour-row" style="top:${topPx}px">
        <div class="tl-hour-label">${pad(h)}:00</div>
        ${h < 24 ? `<div class="tl-half-line" style="top:${HOUR_H / 2}px"></div>` : ""}
      </div>`;
  }).join("");

  // 当前时间红线（仅今天）
  const nowLinePx = isToday ? (currentMinuteOffset() / 60) * HOUR_H : -1;
  const nowLineHtml = isToday
    ? `<div class="tl-now-line" id="pms-now-line" style="top:${nowLinePx.toFixed(1)}px">
         <div class="tl-now-dot"></div>
         <div class="tl-now-label">${minutesToHhmm(currentMinuteOffset())}</div>
       </div>`
    : "";

  // 重叠检测：两块重叠时并列（简单算法：最多两列）
  const positioned = computeLayout(blocks, dateKey);

  const blocksHtml = positioned.map(({ block, top, height, col, totalCols }) =>
    renderBlockCard(block, top, height, col, totalCols, dateKey),
  ).join("");

  const totalH = 24 * HOUR_H;

  return `
<div class="tl-inner" style="height:${totalH}px" id="pms-tl-inner">
  <div class="tl-hours">${hoursHtml}</div>
  <div class="tl-col">
    ${nowLineHtml}
    ${blocksHtml}
    ${blocks.length === 0 ? renderTimelineEmpty() : ""}
  </div>
</div>`;
}

function renderTimelineEmpty(): string {
  return `
<div class="tl-empty">
  <div class="tl-empty-title">${esc(T.timeline.emptyTitle)}</div>
  <div class="tl-empty-hint">${esc(T.timeline.emptyHint)}</div>
</div>`;
}

/* ── 卡片渲染 ────────────────────────────────────────────── */

function renderBlockCard(
  b: WjbTimeBlock,
  topPx: number,
  heightPx: number,
  col: number,
  totalCols: number,
  dateKey: string,
): string {
  const cdState = crossDayState(b.start, b.end, dateKey);
  const isRunning = b.status === "running";
  const isDone = b.status === "done";

  const stateCls = isRunning ? " tbl-running"
    : isDone ? " tbl-done"
    : " tbl-planned";

  const cdCls = cdState === "cross_start" ? " tbl-cd-start"
    : cdState === "cross_end" ? " tbl-cd-end" : "";

  // 来源 / 主标题
  const sourceTitle = _resolveTitle(b);
  const sourceLabel = _resolveSourceLabel(b);

  // 内联状态按钮（不在按钮上重复 data-block-id，由 appShell 从父卡片 data-block-id 读取）
  const actionBtn = isDone
    ? `<button class="tbl-action-btn tbl-action-review" data-act="tl-card-review" type="button">${esc(T.block.actionReview)}</button>`
    : isRunning
    ? `<button class="tbl-action-btn tbl-action-done" data-act="tl-card-done" type="button">${esc(T.block.actionDone)}</button>`
    : `<button class="tbl-action-btn tbl-action-start" data-act="tl-card-start" type="button">${esc(T.block.actionStart)}</button>`;

  // 宽度 / 位置（重叠处理）
  const leftPct = totalCols > 1 ? (col / totalCols * 100) : 0;
  const widthPct = totalCols > 1 ? (100 / totalCols - 0.5) : 100;

  // 跨日标识
  const cdBadge = cdState === "cross_start"
    ? `<div class="tbl-cd-badge">${esc(T.timeline.crossDayContinues)} ${esc(fmtTime(b.end))}</div>`
    : cdState === "cross_end"
    ? `<div class="tbl-cd-badge">${esc(T.timeline.crossDayFrom)}</div>`
    : "";

  const isShort = heightPx < 32;

  return `
<div class="tbl-block${stateCls}${cdCls}"
     style="top:${topPx.toFixed(1)}px;height:${heightPx.toFixed(1)}px;left:${leftPct.toFixed(1)}%;width:${widthPct.toFixed(1)}%;"
     data-block-id="${esc(b.id)}"
     title="${esc(sourceTitle)}">
  <div class="tbl-strip"></div>
  <div class="tbl-body">
    ${isRunning ? `<div class="tbl-running-badge">${esc(T.block.statusRunningBadge)}</div>` : ""}
    ${isShort
      ? `<div class="tbl-title tbl-single">${esc(sourceTitle)}</div>`
      : `<div class="tbl-title">${esc(sourceTitle)}</div>
         <div class="tbl-time">${esc(fmtTime(b.start))} — ${esc(fmtTime(b.end))}</div>
         ${sourceLabel && heightPx >= 64 ? `<div class="tbl-source">${esc(sourceLabel)}</div>` : ""}
         ${cdBadge}`
    }
    ${actionBtn}
  </div>
</div>`;
}

/* ── 重叠布局计算（简单两列策略）────────────────────────── */

interface BlockLayout {
  block: WjbTimeBlock;
  top: number;
  height: number;
  col: number;
  totalCols: number;
}

function computeLayout(blocks: WjbTimeBlock[], dateKey: string): BlockLayout[] {
  const sorted = [...blocks].sort(
    (a, b) => new Date(a.start).getTime() - new Date(b.start).getTime(),
  );

  const result: BlockLayout[] = [];
  const placed: { start: number; end: number; col: number }[] = [];

  for (const block of sorted) {
    const top = (minutesFromDayStart(block.start, dateKey) / 60) * HOUR_H;
    const dur = blockDurationMinutes(block.start, block.end, dateKey);
    const height = Math.max(16, (dur / 60) * HOUR_H);
    const endPx = top + height;

    // 找已占用哪些列
    const colsUsed = new Set(
      placed
        .filter((p) => p.end > top && p.start < endPx)
        .map((p) => p.col),
    );

    let col = 0;
    while (colsUsed.has(col)) col++;

    placed.push({ start: top, end: endPx, col });

    // 更新所有重叠块的 totalCols
    const maxCol = col + 1;
    result.push({ block, top, height, col, totalCols: maxCol });
  }

  // 二次遍历：补齐同组内最大列数
  for (let i = 0; i < result.length; i++) {
    const ri = result[i];
    for (let j = 0; j < result.length; j++) {
      const rj = result[j];
      const overlap = ri.top < rj.top + rj.height && ri.top + ri.height > rj.top;
      if (overlap) {
        const mx = Math.max(ri.totalCols, rj.totalCols);
        result[i].totalCols = mx;
        result[j].totalCols = mx;
      }
    }
  }

  return result;
}

/* ── 辅助 ────────────────────────────────────────────────── */

function _resolveTitle(b: WjbTimeBlock): string {
  if ((b.source === "task" || !b.source) && b.taskId) {
    const task = findTask(b.taskId);
    if (task) return task.title;
  }
  return b.title || "（无标题）";
}

function _resolveSourceLabel(b: WjbTimeBlock): string {
  if (b.source === "task" && b.taskId) return T.block.sourcePrefixTask;
  if (b.source === "periodic") return T.block.sourcePrefixPeriodic;
  if (b.source === "ai_draft") return T.block.sourcePrefixAiDraft;
  return "";
}

function minutesToHhmm(mins: number): string {
  return `${pad(Math.floor(mins / 60) % 24)}:${pad(mins % 60)}`;
}

function pad(n: number): string { return String(n).padStart(2, "0"); }

function esc(s: string): string {
  return (s ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!,
  );
}
