/**
 * 时间块 Popover v0.2 · M1-New.3R
 *
 * 替代旧 timeBlockDrawer：采用近旁弹出定位，不做全屏侧抽屉。
 * 宽度 preferred 420px，碰撞检测（右→左→上移→居中）。
 * 事件全部由 appShell 根委托分发。
 */

import { T } from "../i18n";
import {
  createTimeBlock,
  updateTimeBlock,
  deleteTimeBlock,
  findTimeBlock,
  findTask,
} from "../data/actions";
import { localDateKey } from "../data/types";
import {
  fmtTime,
  composeDatetime,
  addDays,
  durationLabel,
  isCrossDay,
  minutesToHhmm,
  hhmmToMinutes,
  currentMinuteOffset,
  snapMinutes,
  getCalendarDays,
  thisWeekFriday,
  nextMonday,
  friendlyDate,
} from "../lib/timeUtils";

const POPOVER_ID = "pms-tb-popover";

interface PopoverState {
  blockId: string | null;
  date: string;
  startHhmm: string;
  endHhmm: string;
  title: string;
  status: "planned" | "running" | "done";
  taskId: string | null;
  isEndNextDay: boolean;
  showDeleteConfirm: boolean;
  showDatePicker: boolean;
  dpViewYear: number;
  dpViewMonth: number;
  showStartTimePicker: boolean;
  showEndTimePicker: boolean;
  errMsg: string;
}

let _state: PopoverState | null = null;
let _afterChange: (() => void) | null = null;
let _anchorRect: DOMRect | null = null;

export function setPopoverAfterChange(cb: () => void): void {
  _afterChange = cb;
}

export function openTimeBlockPopover(blockId?: string, anchorEl?: HTMLElement): void {
  const today = localDateKey();

  if (blockId) {
    const b = findTimeBlock(blockId);
    if (!b) return;
    const startD = new Date(b.start);
    const endD = new Date(b.end);
    const [sy, sm] = [startD.getFullYear(), startD.getMonth() + 1];
    _state = {
      blockId,
      date: localDateKey(startD),
      startHhmm: `${pad(startD.getHours())}:${pad(startD.getMinutes())}`,
      endHhmm: `${pad(endD.getHours())}:${pad(endD.getMinutes())}`,
      title: b.title,
      status: b.status,
      taskId: b.taskId ?? null,
      isEndNextDay: isCrossDay(b.start, b.end),
      showDeleteConfirm: false,
      showDatePicker: false,
      dpViewYear: sy,
      dpViewMonth: sm,
      showStartTimePicker: false,
      showEndTimePicker: false,
      errMsg: "",
    };
  } else {
    const now = new Date();
    const h = now.getHours();
    const raw = Math.ceil(now.getMinutes() / 30) * 30;
    const snap = raw >= 60 ? 0 : raw;
    const startH = raw >= 60 ? (h + 1 >= 24 ? 23 : h + 1) : h;
    const endH = startH + 1 >= 24 ? 23 : startH + 1;
    const [sy, sm] = [now.getFullYear(), now.getMonth() + 1];
    _state = {
      blockId: null,
      date: today,
      startHhmm: `${pad(startH)}:${pad(snap)}`,
      endHhmm: `${pad(endH)}:${pad(snap)}`,
      title: "",
      status: "planned",
      taskId: null,
      isEndNextDay: false,
      showDeleteConfirm: false,
      showDatePicker: false,
      dpViewYear: sy,
      dpViewMonth: sm,
      showStartTimePicker: false,
      showEndTimePicker: false,
      errMsg: "",
    };
  }

  _anchorRect = anchorEl?.getBoundingClientRect() ?? null;
  _mount();
}

export function closeTimeBlockPopover(): void {
  document.getElementById(POPOVER_ID)?.remove();
  document.getElementById(`${POPOVER_ID}-scrim`)?.remove();
  _state = null;
  _anchorRect = null;
}

export function isPopoverOpen(): boolean {
  return !!document.getElementById(POPOVER_ID);
}

function _mount(): void {
  document.getElementById(POPOVER_ID)?.remove();
  document.getElementById(`${POPOVER_ID}-scrim`)?.remove();
  if (!_state) return;

  const scrim = document.createElement("div");
  scrim.id = `${POPOVER_ID}-scrim`;
  scrim.style.cssText = "position:fixed;inset:0;z-index:499;";
  scrim.setAttribute("data-act", "close-tb-popover");
  document.body.appendChild(scrim);

  const el = document.createElement("div");
  el.id = POPOVER_ID;
  el.className = "tbp-wrap";
  el.innerHTML = _buildHtml(_state);
  document.body.appendChild(el);
  _positionPopover(el);

  setTimeout(() => {
    el.querySelector<HTMLInputElement>(".tbp-title-input")?.focus();
  }, 50);
}

function _repaint(): void {
  if (!_state) return;
  const el = document.getElementById(POPOVER_ID);
  if (!el) return;
  el.innerHTML = _buildHtml(_state);
  _positionPopover(el);
}

function _positionPopover(el: HTMLElement): void {
  const PW = 420;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const rect = _anchorRect;
  let left: number, top: number;

  if (rect) {
    if (rect.right + PW + 8 <= vw - 8) {
      left = rect.right + 8; top = rect.top;
    } else if (rect.left - PW - 8 >= 8) {
      left = rect.left - PW - 8; top = rect.top;
    } else {
      left = Math.max(8, (vw - PW) / 2); top = 80;
    }
  } else {
    left = Math.max(8, (vw - PW) / 2); top = 80;
  }

  const elH = el.scrollHeight || 480;
  if (top + elH > vh - 16) top = Math.max(16, vh - elH - 16);

  el.style.cssText = `position:fixed;left:${left}px;top:${top}px;width:${PW}px;z-index:500;`;
}

/* ── HTML builder ───────────────────────────────────────────── */

function _buildHtml(s: PopoverState): string {
  if (s.showDeleteConfirm) return _buildDeleteConfirmHtml();

  const isEdit = !!s.blockId;
  const today = localDateKey();

  // 来源行
  let sourceRow = "";
  if (isEdit && s.taskId) {
    const task = findTask(s.taskId);
    const name = task ? esc(task.title) : "（任务已删除）";
    sourceRow = `<div class="tbp-source-row">
      <span class="tbp-source-badge">来源：任务 &middot; ${name}</span>
      ${task ? `<button class="tbp-source-link" data-act="tbp-view-task" data-task-id="${esc(s.taskId)}" type="button">查看</button>` : ""}
    </div>`;
  }

  // 状态分段
  const statuses = [
    { k: "planned", l: T.popover.statusPlanned },
    { k: "running", l: T.popover.statusRunning },
    { k: "done",    l: T.popover.statusDone },
  ];
  const seg = statuses.map((st) =>
    `<button class="tbp-seg-btn${s.status === st.k ? " is-active" : ""}"
      data-act="tbp-status" data-value="${st.k}" type="button">${esc(st.l)}</button>`,
  ).join("");

  // 跨日相关
  const endEarlyHint = !s.isEndNextDay && _isEndEarlier(s)
    ? `<div class="tbp-endnextday-hint">${esc(T.popover.errEndEarly)}
        <button class="tbp-btn-sm" data-act="tbp-confirm-nextday" type="button">${esc(T.popover.confirmNextDay)}</button>
        <button class="tbp-btn-sm is-ghost" data-act="tbp-cancel-nextday" type="button">${esc(T.popover.confirmNo)}</button>
       </div>` : "";

  const crossDayLabel = s.isEndNextDay
    ? `<div class="tbp-cross-day-label">跨日 · 次日 ${esc(s.endHhmm)}（共 ${esc(_calcDuration(s))}）</div>` : "";

  const errHtml = s.errMsg ? `<div class="tbp-err">${esc(s.errMsg)}</div>` : "";

  // 日期按钮文案
  const dateBtnLabel = friendlyDate(s.date, today);

  return `
<div class="tbp-head">
  <div class="tbp-head-title">${esc(isEdit ? T.popover.titleEdit : T.popover.titleCreate)}</div>
  <button class="tbp-close" data-act="close-tb-popover" type="button">&#x2715;</button>
</div>
${sourceRow}
<div class="tbp-body">
  <input class="tbp-title-input" type="text"
    placeholder="${esc(T.popover.placeholder)}"
    value="${esc(s.title)}"
    data-act="tbp-title-input"
    autocomplete="off" />
  ${errHtml}
  <div class="tbp-field-row">
    <span class="tbp-field-lbl">${esc(T.popover.fieldStatus)}</span>
    <div class="tbp-seg">${seg}</div>
  </div>
  <div class="tbp-field-row">
    <span class="tbp-field-lbl">${esc(T.popover.fieldDate)}</span>
    <button class="tbp-field-btn${s.showDatePicker ? " is-active" : ""}"
      data-act="tbp-toggle-date" type="button">${esc(dateBtnLabel)}</button>
  </div>
  ${s.showDatePicker ? _buildInlineDatePicker(s) : ""}
  <div class="tbp-field-row">
    <span class="tbp-field-lbl">${esc(T.popover.fieldTime)}</span>
    <div class="tbp-time-row">
      <button class="tbp-field-btn${s.showStartTimePicker ? " is-active" : ""}"
        data-act="tbp-toggle-start-tp" type="button">${esc(s.startHhmm)}</button>
      <span class="tbp-time-sep">—</span>
      <button class="tbp-field-btn${s.showEndTimePicker ? " is-active" : ""}${s.isEndNextDay ? " tbp-nextday" : ""}"
        data-act="tbp-toggle-end-tp" type="button">${esc(s.endHhmm)}</button>
    </div>
  </div>
  ${endEarlyHint}
  ${crossDayLabel}
  ${s.showStartTimePicker ? _buildInlineTimePicker("start", s.startHhmm, s.startHhmm) : ""}
  ${s.showEndTimePicker ? _buildInlineTimePicker("end", s.endHhmm, s.startHhmm) : ""}
</div>
<div class="tbp-footer">
  ${isEdit ? `<button class="tbp-del-btn" data-act="tbp-delete" type="button">${esc(T.popover.btnDelete)}</button>` : ""}
  ${isEdit && s.status === "done"
    ? `<button class="tbp-review-btn" data-act="tbp-open-review" type="button">${esc(T.popover.btnReview)}</button>`
    : ""}
  <div style="flex:1"></div>
  <button class="tbp-ghost-btn" data-act="close-tb-popover" type="button">${esc(T.popover.btnCancel)}</button>
  <button class="tbp-save-btn" data-act="tbp-save" type="button">${esc(T.popover.btnSave)}</button>
</div>`;
}

function _buildDeleteConfirmHtml(): string {
  return `
<div class="tbp-body" style="padding:20px 16px;">
  <div class="tbp-dc-title">${esc(T.popover.deleteConfirmTitle)}</div>
  <div class="tbp-dc-desc">${esc(T.popover.deleteConfirmDesc)}</div>
  <div class="tbp-dc-actions">
    <button class="tbp-ghost-btn" data-act="tbp-cancel-delete" type="button">${esc(T.popover.deleteConfirmCancel)}</button>
    <button class="tbp-danger-btn" data-act="tbp-confirm-delete" type="button">${esc(T.popover.deleteConfirmOk)}</button>
  </div>
</div>`;
}

function _buildInlineDatePicker(s: PopoverState): string {
  const today = localDateKey();
  const days = getCalendarDays(s.dpViewYear, s.dpViewMonth);
  const shortcuts = [
    { k: today, l: T.datePicker.today },
    { k: addDays(today, 1), l: T.datePicker.tomorrow },
    { k: thisWeekFriday(today), l: T.datePicker.thisWeekFriday },
    { k: nextMonday(today), l: T.datePicker.nextMonday },
  ];
  const cells = days.map(({ key, date, isCurrentMonth }) => {
    const cls = ["dp-cell", key === today ? "dp-today" : "",
      key === s.date ? "dp-selected" : "", !isCurrentMonth ? "dp-other" : ""].filter(Boolean).join(" ");
    return `<div class="${cls}" data-act="tbp-pick-date" data-value="${esc(key)}">${date}</div>`;
  }).join("");
  return `<div class="tbp-inline-dp">
    <div class="dp-header">
      <button class="dp-nav-btn" data-act="tbp-dp-prev" type="button">&#8249;</button>
      <div class="dp-title">${s.dpViewYear}年${s.dpViewMonth}月</div>
      <button class="dp-nav-btn" data-act="tbp-dp-next" type="button">&#8250;</button>
    </div>
    <div class="dp-shortcuts">
      ${shortcuts.map((sc) => `<button class="dp-shortcut${sc.k === s.date ? " dp-sc-active" : ""}" data-act="tbp-pick-date" data-value="${esc(sc.k)}" type="button">${esc(sc.l)}</button>`).join("")}
    </div>
    <div class="dp-weekdays">${T.datePicker.weekdays.map((w) => `<div class="dp-wd">${esc(w)}</div>`).join("")}</div>
    <div class="dp-grid">${cells}</div>
  </div>`;
}

function _buildInlineTimePicker(which: "start" | "end", value: string, refHhmm: string): string {
  const refMins = hhmmToMinutes(refHhmm);
  const nowSnapped = snapMinutes(currentMinuteOffset(), 30);
  const selMins = hhmmToMinutes(value);
  const nextHourMins = Math.ceil((refMins + 1) / 60) * 60;

  const quickBtns = which === "end" ? [
    { l: T.timePicker.quickAdd30m, m: refMins + 30 },
    { l: T.timePicker.quickAdd1h,  m: refMins + 60 },
    { l: T.timePicker.quickAdd2h,  m: refMins + 120 },
    { l: T.timePicker.quickToNextHour, m: nextHourMins },
  ] : [];

  const items: string[] = [];
  for (let m = 0; m < 24 * 60; m += 30) {
    const hhmm = minutesToHhmm(m);
    const isSel = m === selMins;
    const isNow = m === nowSnapped;
    const label = isNow ? `${hhmm}${T.timePicker.nowSuffix}` : hhmm;
    const cls = ["tp-opt", isSel ? "tp-opt-selected" : "", isNow && !isSel ? "tp-opt-now" : ""].filter(Boolean).join(" ");
    items.push(`<div class="${cls}" data-act="tbp-pick-time" data-which="${which}" data-mins="${m}">${esc(label)}</div>`);
  }

  return `<div class="tbp-inline-tp">
    ${quickBtns.length ? `<div class="tp-quicks">
      ${quickBtns.map((b) => `<button class="tp-quick-btn" data-act="tbp-pick-time-quick" data-which="${which}" data-mins="${b.m}" type="button">${esc(b.l)}</button>`).join("")}
    </div>` : ""}
    <div class="tp-list" style="max-height:160px;overflow-y:auto">${items.join("")}</div>
  </div>`;
}

/* ── 事件处理（appShell 根委托调用）────────────────────────── */

export function handlePopoverClick(act: string, target: HTMLElement): void {
  if (!_state) return;
  switch (act) {
    case "close-tb-popover": closeTimeBlockPopover(); return;
    case "tbp-status": {
      const v = target.dataset.value as PopoverState["status"];
      if (v) { _state.status = v; _repaint(); } return;
    }
    case "tbp-toggle-date":
      _state.showDatePicker = !_state.showDatePicker;
      _state.showStartTimePicker = false; _state.showEndTimePicker = false;
      _repaint(); return;
    case "tbp-dp-prev":
      _state.dpViewMonth -= 1;
      if (_state.dpViewMonth < 1) { _state.dpViewMonth = 12; _state.dpViewYear -= 1; }
      _repaint(); return;
    case "tbp-dp-next":
      _state.dpViewMonth += 1;
      if (_state.dpViewMonth > 12) { _state.dpViewMonth = 1; _state.dpViewYear += 1; }
      _repaint(); return;
    case "tbp-pick-date": {
      const d = target.dataset.value;
      if (d) { _state.date = d; _state.showDatePicker = false; _repaint(); } return;
    }
    case "tbp-toggle-start-tp":
      _state.showStartTimePicker = !_state.showStartTimePicker;
      _state.showEndTimePicker = false; _state.showDatePicker = false;
      _repaint(); return;
    case "tbp-toggle-end-tp":
      _state.showEndTimePicker = !_state.showEndTimePicker;
      _state.showStartTimePicker = false; _state.showDatePicker = false;
      _repaint(); return;
    case "tbp-pick-time": {
      const w = target.dataset.which as "start" | "end";
      const m = Number(target.dataset.mins);
      if (w === "start") { _state.startHhmm = minutesToHhmm(m); _state.showStartTimePicker = false; }
      else { _state.endHhmm = minutesToHhmm(m); _state.showEndTimePicker = false; }
      _state.errMsg = ""; _repaint(); return;
    }
    case "tbp-pick-time-quick": {
      const w = target.dataset.which as "start" | "end";
      const raw = Number(target.dataset.mins);
      const hhmm = minutesToHhmm(raw >= 24 * 60 ? raw % (24 * 60) : raw);
      if (w === "start") { _state.startHhmm = hhmm; _state.showStartTimePicker = false; }
      else { _state.endHhmm = hhmm; _state.showEndTimePicker = false; }
      _state.errMsg = ""; _repaint(); return;
    }
    case "tbp-confirm-nextday":
      _state.isEndNextDay = true; _state.errMsg = ""; _repaint(); return;
    case "tbp-cancel-nextday":
      _state.isEndNextDay = false; _repaint(); return;
    case "tbp-save": _handleSave(); return;
    case "tbp-delete":
      _state.showDeleteConfirm = true; _repaint(); return;
    case "tbp-cancel-delete":
      _state.showDeleteConfirm = false; _repaint(); return;
    case "tbp-confirm-delete":
      if (_state.blockId) { deleteTimeBlock(_state.blockId); closeTimeBlockPopover(); _afterChange?.(); } return;
    case "tbp-view-task": {
      const tid = target.dataset.taskId;
      if (tid) {
        closeTimeBlockPopover();
        document.dispatchEvent(new CustomEvent("pms-open-task-drawer", { detail: { taskId: tid } }));
      } return;
    }
    case "tbp-open-review":
      // reviewFlyout 事件由 appShell 统一委托（data-act="tbp-open-review" → appShell → openReviewFlyout）
      // 这里不重复处理，让事件冒泡到 appShell 的 tl-card-review 分支
      return;
  }
}

export function handlePopoverInput(target: HTMLInputElement): void {
  if (!_state) return;
  if (target.classList.contains("tbp-title-input")) {
    _state.title = target.value;
    _state.errMsg = "";
  }
}

function _handleSave(): void {
  if (!_state) return;
  if (!_state.title.trim()) {
    _state.errMsg = T.popover.errTitle; _repaint(); return;
  }
  const startIso = composeDatetime(_state.date, _state.startHhmm);
  const endDate = _state.isEndNextDay ? addDays(_state.date, 1) : _state.date;
  const endIso = composeDatetime(endDate, _state.endHhmm);
  if (!_state.isEndNextDay && new Date(endIso).getTime() <= new Date(startIso).getTime()) {
    _state.errMsg = T.popover.errEndEarly; _repaint(); return;
  }
  if (_state.blockId) {
    updateTimeBlock(_state.blockId, {
      title: _state.title.trim(), start: startIso, end: endIso, status: _state.status,
    });
  } else {
    createTimeBlock({ title: _state.title.trim(), start: startIso, end: endIso, status: _state.status });
  }
  closeTimeBlockPopover();
  _afterChange?.();
}

function _isEndEarlier(s: PopoverState): boolean {
  return hhmmToMinutes(s.endHhmm) < hhmmToMinutes(s.startHhmm);
}

function _calcDuration(s: PopoverState): string {
  const sm = hhmmToMinutes(s.startHhmm);
  const em = hhmmToMinutes(s.endHhmm);
  return durationLabel(Math.max(0, s.isEndNextDay ? (24 * 60 - sm) + em : em - sm));
}

function pad(n: number): string { return String(n).padStart(2, "0"); }
function esc(s: string): string {
  return (s ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!,
  );
}

