import { T } from "../i18n";

/**
 * AI 建议卡片 · M1-New.2 仍是占位
 * 固定 3 段「建议 / 原因 / 操作」结构；不接 AI 真调用。
 * 按钮文案中文（采纳 / 忽略 / 编辑后采纳）。
 */
interface AiPlaceholder {
  id:     string;
  advice: string;
  reason: string;
}

const DEFAULT_AI: AiPlaceholder = {
  id:     "ai-placeholder",
  advice: "将当前任务拆成 3 个子任务",
  reason: "当前任务预计超过 90 分钟，连续作业易疲劳",
};

export function renderAiSuggestionCard(s: AiPlaceholder = DEFAULT_AI): string {
  return `
    <div class="pms-ai-suggestion-card" data-ai-id="${esc(s.id)}">
      <div class="pms-ai-suggestion-card-row">
        <span class="pms-ai-suggestion-card-label">${T.ai.label}</span>
        <span class="pms-ai-suggestion-card-value">${esc(s.advice)}</span>
      </div>
      <div class="pms-ai-suggestion-card-row">
        <span class="pms-ai-suggestion-card-label">${T.ai.reason}</span>
        <span class="pms-ai-suggestion-card-value">${esc(s.reason)}</span>
      </div>
      <div class="pms-ai-suggestion-card-row">
        <span class="pms-ai-suggestion-card-label">${T.ai.action}</span>
        <div class="pms-ai-suggestion-card-actions">
          <button class="pms-primary-button" data-ai-act="accept" type="button">${T.ai.accept}</button>
          <button class="pms-secondary-button" data-ai-act="ignore" type="button">${T.ai.ignore}</button>
          <button class="pms-text-button" data-ai-act="edit" type="button">${T.ai.editAndAccept}</button>
        </div>
      </div>
    </div>
  `;
}

function esc(s: string): string {
  return (s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
}
