/**
 * 无限进步 M1-New.3R 主壳
 *
 * 四栏布局：左导航 + 任务池面板 + 时间轴 + 右侧信息栏
 * 事件全部根委托（#app）
 */

import { T } from "./i18n";
import { renderTopbar } from "./components/topbar";
import { renderSidebar } from "./components/sidebar";
import { renderTimeline, getViewDate, setViewDate, goToToday, goNextDay, goPrevDay } from "./components/timeline";
import { renderTaskPool, setPoolFilter, togglePoolCollapsed, bindPoolDragEvents } from "./components/taskPool";
import { renderRightSidebar } from "./components/rightSidebar";
import {
  renderTaskDetailDrawer,
  openDrawer,
  closeDrawer,
  setDrawerAfterChange,
} from "./components/taskDetailDrawer";
import {
  openTimeBlockPopover,
  closeTimeBlockPopover,
  isPopoverOpen,
  setPopoverAfterChange,
  handlePopoverClick,
  handlePopoverInput,
} from "./components/timeBlockPopover";
import { openReviewFlyout, handleReviewFlyoutClick, closeReviewFlyout } from "./components/reviewFlyout";
import { openAiScheduleCard, closeAiScheduleCard, handleAiCardClick, setAiCardAfterApply } from "./components/aiScheduleCard";
import {
  openTimelineDatePicker,
  closeTimelineDatePicker,
  isTimelineDatePickerOpen,
  handleTimelineDatePickerClick,
} from "./components/timelineDatePicker";
import { renderButtonShowcase } from "./components/buttons";
import { renderInputShowcase } from "./components/inputs";
import { renderCardShowcase } from "./components/taskCard";
import { renderAiSuggestionCard } from "./components/aiSuggestionCard";
import { renderStateShowcase } from "./components/stateAndFeedback";
import { storeSnapshot, inboxCount, allActiveCount, doneCount } from "./data/selectors";
import { createTask, setTimeBlockStatus, findTask, createTimeBlock } from "./data/actions";
import { resetStore, getFallbackReason } from "./data/storage";
import { STORAGE_KEY, SCHEMA_VERSION } from "./data/types";
import { HOUR_H } from "./components/timeline";
import { composeDatetime, minutesToHhmm, snapMinutes } from "./lib/timeUtils";

export function initAppShell(): void {
  const root = document.getElementById("app");
  if (!root) return;

  const url = new URL(window.location.href);
  if (url.searchParams.get("demo") === "components") {
    renderPreviewPage(root);
    return;
  }

  renderMainPage(root);
  bindMainPageEvents(root);

  setDrawerAfterChange(() => rerenderMainPartials());
  setPopoverAfterChange(() => rerenderMainPartials());
  setAiCardAfterApply(() => rerenderMainPartials());

  document.addEventListener("pms-open-task-drawer", (e) => {
    const taskId = (e as CustomEvent<{ taskId: string }>).detail?.taskId;
    if (taskId) openDrawer(taskId);
  });
}

/* ── 主页渲染 ──────────────────────────────────────────── */

function renderMainPage(root: HTMLElement): void {
  root.className = "pms-app-m1";
  root.innerHTML = `
    ${renderTopbar()}
    <div class="pms-app-body">
      ${renderSidebar()}
      ${renderTaskPool()}
      <div class="pms-content-area">
        ${renderTimeline()}
      </div>
      ${renderRightSidebar()}
    </div>
    ${renderTaskDetailDrawer()}
    ${renderSettingsModalShell()}
    ${renderChangelogModalShell()}
  `;

  const pool = document.getElementById("pms-pool-list");
  if (pool) bindPoolDragEvents(pool);
  bindLocalInputs();

  // 滚动到当前时间
  setTimeout(() => {
    const scroll = document.getElementById("pms-tl-scroll");
    const nowLine = document.getElementById("pms-now-line");
    if (scroll && nowLine) {
      const lineTop = parseInt(nowLine.style.top || "0", 10);
      scroll.scrollTop = Math.max(0, lineTop - scroll.clientHeight / 3);
    }
  }, 100);
}

function rerenderMainPartials(): void {
  const root = document.getElementById("app");
  if (!root) return;

  const sidebar = root.querySelector(".pms-sidebar");
  const pool = root.querySelector(".pms-taskpool");
  const tl = root.querySelector(".tl-container");
  const right = root.querySelector(".pms-right-sidebar");

  if (sidebar) sidebar.outerHTML = renderSidebar();
  if (pool) pool.outerHTML = renderTaskPool();
  if (tl) tl.outerHTML = renderTimeline();
  if (right) right.outerHTML = renderRightSidebar();

  const newPool = document.getElementById("pms-pool-list");
  if (newPool) bindPoolDragEvents(newPool);
  bindLocalInputs();
}

/* ── 事件绑定 ──────────────────────────────────────────── */

function bindMainPageEvents(root: HTMLElement): void {
  // ── document 级委托：处理挂在 body 外的浮层（Popover / AI卡片 / 复盘）──
  // 必须用 document 而非 root(#app)，因为这三个组件挂在 document.body 下，
  // 事件不会冒泡经过 #app。
  document.addEventListener("click", (e) => {
    const target = e.target as Element;

    // Popover 内部按钮
    const tbpEl = target.closest<HTMLElement>("[data-act^='tbp-'], [data-act='close-tb-popover']");
    if (tbpEl && isPopoverOpen()) {
      handlePopoverClick(tbpEl.dataset.act!, tbpEl);
      e.stopPropagation();
      return;
    }

    // AI 安排日程卡片（含 scrim 关闭）
    const aiActEl = target.closest<HTMLElement>("[data-act^='ai-'], [data-act='close-ai-schedule']");
    if (aiActEl) {
      const act = aiActEl.dataset.act!;
      handleAiCardClick(act, aiActEl);
      e.stopPropagation();
      return;
    }

    // 复盘浮层
    const rfEl = target.closest<HTMLElement>("[data-act='close-review'], [data-act='save-review']");
    if (rfEl) {
      handleReviewFlyoutClick(rfEl.dataset.act!);
      e.stopPropagation();
      return;
    }

    // 时间轴日期标题选择器（含 scrim 关闭）
    const tldpEl = target.closest<HTMLElement>("[data-act^='tldp-'], [data-act='close-tldp']");
    if (tldpEl && isTimelineDatePickerOpen()) {
      handleTimelineDatePickerClick(tldpEl.dataset.act!, tldpEl);
      e.stopPropagation();
      return;
    }
  });

  // Popover 标题实时输入（也在 body 外，需 document 级）
  document.addEventListener("input", (e) => {
    const t = e.target as HTMLInputElement;
    if (isPopoverOpen() && t.classList.contains("tbp-title-input")) {
      handlePopoverInput(t);
    }
  });

  root.addEventListener("click", (e) => {
    const target = e.target as Element;

    // 通用 data-act
    const actEl = target.closest<HTMLElement>("[data-act]");
    if (actEl) {
      const act = actEl.dataset.act!;

      if (act === "open-changelog") { openModal("pms-changelog-modal"); return; }
      if (act === "open-settings")  { openModal("pms-settings-modal"); return; }
      if (act === "close-modal")    {
        if (actEl.classList.contains("pms-modal-scrim") && actEl !== target) return;
        closeAllModals(); return;
      }
      if (act === "close-drawer")   { closeDrawer(); return; }
      if (act === "settings-reset") { handleResetData(); return; }
      if (act === "open-ai-schedule") { openAiScheduleCard(); return; }

      // 时间轴导航
      if (act === "tl-prev-day")  { goPrevDay(); rerenderMainPartials(); return; }
      if (act === "tl-next-day")  { goNextDay(); rerenderMainPartials(); return; }
      if (act === "tl-today")     { goToToday(); rerenderMainPartials(); return; }

      // 时间轴日期标题 → 打开自定义日期选择器
      if (act === "tl-open-date-picker") {
        openTimelineDatePicker(getViewDate(), actEl as HTMLElement, (dateKey) => {
          setViewDate(dateKey);
          rerenderMainPartials();
        });
        return;
      }

      // 任务池
      if (act === "pool-collapse") { togglePoolCollapsed(); rerenderMainPartials(); return; }
      if (act === "pool-filter") {
        const v = actEl.dataset.value as Parameters<typeof setPoolFilter>[0];
        if (v) { setPoolFilter(v); rerenderMainPartials(); }
        return;
      }
      if (act === "pool-arrange" || act === "pool-rearrange") {
        openTimeBlockPopover(undefined, actEl as HTMLElement);
        return;
      }

      // 新增时间块
      if (act === "add-timeblock") {
        openTimeBlockPopover(undefined, actEl as HTMLElement);
        return;
      }

      // 卡片内联操作（blockId 从最近的父卡片 data-block-id 读，不依赖按钮本身）
      if (act === "tl-card-start" || act === "tl-card-done" || act === "tl-card-review") {
        const cardEl = actEl.closest<HTMLElement>("[data-block-id]");
        const bid = cardEl?.dataset.blockId;
        if (!bid) return;
        if (act === "tl-card-start") { setTimeBlockStatus(bid, "running"); rerenderMainPartials(); }
        else if (act === "tl-card-done") { setTimeBlockStatus(bid, "done"); rerenderMainPartials(); }
        else if (act === "tl-card-review") { openReviewFlyout(bid, actEl as HTMLElement); }
        return;
      }

      return; // 其他 data-act 不冒泡
    }

    // 时间块卡片主体 → Popover
    const blockEl = target.closest<HTMLElement>("[data-block-id]");
    if (blockEl?.dataset.blockId && !(target as HTMLElement).closest("[data-act]")) {
      openTimeBlockPopover(blockEl.dataset.blockId, blockEl);
      return;
    }

    // 任务行 → 详情抽屉
    const taskEl = target.closest<HTMLElement>("[data-task-id]");
    if (taskEl?.dataset.taskId && !(target as HTMLElement).closest("[data-act]")) {
      openDrawer(taskEl.dataset.taskId);
      return;
    }

    // 左栏导航
    const navEl = target.closest<HTMLElement>("[data-nav]");
    if (navEl) {
      root.querySelectorAll(".pms-sidebar-nav-item").forEach((el) => el.classList.remove("is-active"));
      navEl.classList.add("is-active");
    }
  });

  // 拖放：任务 → 时间轴
  root.addEventListener("dragover", (e) => {
    const inner = (e.target as Element).closest("#pms-tl-inner");
    if (inner) e.preventDefault();
  });
  root.addEventListener("drop", (e) => {
    const inner = (e.target as Element).closest<HTMLElement>("#pms-tl-inner");
    if (!inner) return;
    e.preventDefault();
    const taskId = (e as DragEvent).dataTransfer?.getData("text/plain");
    if (!taskId) return;
    _handleDropTask(taskId, e as DragEvent, inner);
  });

  // ESC
  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    if (document.querySelector<HTMLElement>(".pms-modal-scrim[style*='flex']")) { closeAllModals(); return; }
    if (document.getElementById("pms-ai-schedule-card")) { closeAiScheduleCard(); return; }
    if (document.getElementById("pms-review-flyout"))    { closeReviewFlyout(); return; }
    if (isTimelineDatePickerOpen())                       { closeTimelineDatePicker(); return; }
    if (isPopoverOpen())                                  { closeTimeBlockPopover(); return; }
    if (document.getElementById("pms-task-detail-drawer")?.classList.contains("is-open")) { closeDrawer(); return; }
  });

  bindLocalInputs();
}

function bindLocalInputs(): void {
  const capture = document.getElementById("pms-quick-capture") as HTMLInputElement | null;
  if (capture && !capture.dataset.bound) {
    capture.dataset.bound = "1";
    capture.addEventListener("keydown", (e) => {
      if (e.key !== "Enter") return;
      const v = capture.value.trim();
      if (!v) return;
      createTask(v);
      capture.value = "";
      rerenderMainPartials();
      (document.getElementById("pms-quick-capture") as HTMLInputElement | null)?.focus();
    });
  }
}

/* ── 拖放：任务 → 时间轴 ─────────────────────────────── */

function _handleDropTask(taskId: string, e: DragEvent, inner: HTMLElement): void {
  const task = findTask(taskId);
  if (!task) return;

  const rect = inner.getBoundingClientRect();
  const scroll = document.getElementById("pms-tl-scroll");
  const scrollTop = scroll ? scroll.scrollTop : 0;
  const relY = e.clientY - rect.top + scrollTop;
  const rawMins = (relY / HOUR_H) * 60;
  const startMins = Math.max(0, Math.min(snapMinutes(rawMins, 15), 23 * 60));
  const dur = task.aiEstimatedMinutes ?? 60;
  const endMins = Math.min(startMins + dur, 24 * 60 - 1);
  const dateKey = getViewDate();

  createTimeBlock({
    title: task.title,
    start: composeDatetime(dateKey, minutesToHhmm(startMins)),
    end: composeDatetime(dateKey, minutesToHhmm(endMins)),
    taskId,
    source: "task",
  });
  rerenderMainPartials();
}

/* ── 弹窗 ─────────────────────────────────────────────── */

function renderSettingsModalShell(): string {
  const s = storeSnapshot();
  const fallback = getFallbackReason();
  return modalShell(
    "pms-settings-modal",
    T.topbar.settings,
    `<div class="pms-modal-section">
      <div class="pms-modal-section-title">本地数据状态</div>
      ${fallback ? `<p style="color:var(--warning);font-weight:500">提示：${esc(fallback)}</p>` : ""}
      <ul style="list-style:none;padding:0;margin:0;font-size:13px;line-height:1.9">
        <li><strong>schemaVersion：</strong>${esc(SCHEMA_VERSION)}</li>
        <li><strong>存储 key：</strong><code>${esc(STORAGE_KEY)}</code></li>
        <li><strong>任务数：</strong>${s.tasks.length}（未完成 ${allActiveCount()} · 已完成 ${doneCount()} · 收件箱 ${inboxCount()}）</li>
        <li><strong>时间块数：</strong>${s.timeBlocks.length}</li>
        <li><strong>最后更新：</strong>${formatIso(s.meta.updatedAt)}</li>
      </ul>
    </div>
    <div class="pms-modal-section">
      <div class="pms-modal-section-title">数据维护</div>
      <button class="pms-danger-button is-secondary" data-act="settings-reset" type="button">恢复默认种子（清空当前数据）</button>
      <p style="font-size:12px;color:var(--text-3);margin-top:8px">会清空 localStorage 中本产品的数据并恢复为初始种子，不可撤销。</p>
    </div>
    <div class="pms-modal-section">
      <div class="pms-modal-section-title">关于</div>
      <p>${T.brand.name} · ${T.brand.tagline}</p>
      <p style="color:var(--text-3);font-size:12px">M1-New.3R · data schema ${esc(SCHEMA_VERSION)}</p>
    </div>`,
  );
}

