function modalShell(id: string, title: string, body: string): string {
  return `<div class="pms-modal-scrim" id="${id}" data-act="close-modal" style="display:none">
  <div class="pms-modal-card">
    <div class="pms-modal-header">
      <div class="pms-modal-title">${title}</div>
      <button class="pms-icon-button" data-act="close-modal" type="button">
        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none"
          stroke="currentColor" stroke-width="1.75" stroke-linecap="round">
          <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
        </svg>
      </button>
    </div>
    <div class="pms-modal-body">${body}</div>
  </div>
</div>`;
}

function openModal(id: string): void {
  if (id === "pms-settings-modal") {
    const m = document.getElementById("pms-settings-modal");
    if (m) m.outerHTML = renderSettingsModalShell();
  }
  const m = document.getElementById(id);
  if (m) m.style.display = "flex";
}

function closeAllModals(): void {
  document.querySelectorAll<HTMLElement>(".pms-modal-scrim").forEach((m) => {
    m.style.display = "none";
  });
}

let _resetConfirming = false;
function handleResetData(): void {
  const btn = document.querySelector<HTMLButtonElement>('[data-act="settings-reset"]');
  if (!btn) return;
  if (!_resetConfirming) {
    _resetConfirming = true;
    btn.textContent = "再次点击确认恢复（5 秒内有效）";
    btn.classList.remove("is-secondary");
    setTimeout(() => {
      if (!_resetConfirming) return;
      _resetConfirming = false;
      btn.textContent = "恢复默认种子（清空当前数据）";
      btn.classList.add("is-secondary");
    }, 5000);
    return;
  }
  resetStore();
  _resetConfirming = false;
  closeDrawer();
  closeAllModals();
  rerenderMainPartials();
}

