/**
 * 无限进步 M1-New.1 · 组件 CSS 注入
 *
 * 全部 token 来自 tokens.css（v1.5 冻结），不写裸 HEX / 裸 px。
 * 类名前缀 .pms-（与组件命名映射表一致）。状态修饰类用 .is-*。
 * 不引 Tailwind / utility framework；纯手写 CSS。
 */

export function injectStyles(): void {
  if (document.getElementById("pms-m1-styles")) return;
  const style = document.createElement("style");
  style.id = "pms-m1-styles";
  style.textContent = CSS;
  document.head.appendChild(style);
}

