/**
 * 无限进步 · 数据类型 v1（干净 schema · 不背旧字段包袱）
 *
 * 拍板原则（M1-New.2）：
 *   - 不保留旧 tags 字段
 *   - 不保留旧 v_p_unassigned 标识
 *   - 不兼容旧 cadence 字段命名
 *   - 不读旧 localStorage
 *   - projectId: null 表示收件箱 / 未归属
 *   - priority 使用 "P1" | "P2" | "P3" | "P4"，不裸存数字
 *   - 时间一律 ISO 8601 字符串
 *   - schemaVersion / createdAt / updatedAt 必须有
 *
 * M1-New.3R 新增（向后兼容可选字段，schemaVersion 不变）：
 *   - WjbTask.scheduleStatus — 排程状态
 *   - WjbTask.aiEstimatedMinutes — AI 预估工时
 *   - WjbTimeBlock.source — 来源类型
 *   - WjbTimeBlock.reviewNote — 复盘笔记
 *   - WjbTimeBlock.periodicItemId — 关联周期事项（预留）
 */

export type Priority   = "P1" | "P2" | "P3" | "P4";
export type TaskStatus = "todo" | "done";
export type BlockStatus = "planned" | "running" | "done";
export type BlockSource = "manual" | "task" | "periodic" | "ai_draft";
export type ScheduleStatus = "unscheduled" | "partial" | "scheduled" | "done" | "overdue";
export type ProjectColorToken =
  | "--project-1"
  | "--project-2"
  | "--project-3"
  | "--project-4";

export interface WjbTask {
  id: string;
  title: string;
  description?: string;
  projectId: string | null;          // null 表示收件箱 / 未归属
  priority: Priority;
  status: TaskStatus;
  dueDate?: string;                  // YYYY-MM-DD
  createdAt: string;                 // ISO 8601
  updatedAt: string;                 // ISO 8601
  completedAt?: string | null;       // ISO 8601；status=todo 时为 null
  // M1-New.3R 新增（可选，旧数据无此字段时按 undefined 处理）
  scheduleStatus?: ScheduleStatus;   // 排程状态
  aiEstimatedMinutes?: number | null; // AI 预估工时（分钟）
}

export interface WjbProject {
  id: string;
  name: string;
  colorToken: ProjectColorToken;
  createdAt: string;
  updatedAt: string;
}

export interface WjbTimeBlock {
  id: string;
  title: string;
  taskId?: string | null;
  start: string;                     // ISO 8601 with time（内部字段，对应 spec 的 startAt）
  end:   string;                     // ISO 8601 with time（内部字段，对应 spec 的 endAt）
  status: BlockStatus;               // planned=待办 / running=进行中 / done=已完成
  createdAt: string;
  updatedAt: string;
  // M1-New.3R 新增（可选，旧数据无此字段时按 undefined 处理）
  source?: BlockSource;              // 来源：manual / task / periodic / ai_draft
  reviewNote?: string | null;        // 复盘笔记
  periodicItemId?: string | null;    // 关联周期事项 ID（M1-New.3A 实现，此处预留）
}

export interface WjbSettings {
  firstDayOfWeek: "monday" | "sunday";
}

export interface WjbMeta {
  createdAt: string;
  updatedAt: string;
}

/**
 * Routine Rail 每日勾选状态（M1-New.3）
 * 采用单对象方案：date 不等于今天则就地重置，无历史积累、无清理逻辑。
 */
export interface WjbRoutineState {
  date:   string;                   // "YYYY-MM-DD"（本地日期）
  checks: Record<string, boolean>;  // key = RoutineItem.key
}

export interface WjbDataStore {
  schemaVersion: "wuxianjinbu-v1";
  tasks:        WjbTask[];
  projects:     WjbProject[];
  timeBlocks:   WjbTimeBlock[];
  settings:     WjbSettings;
  meta:         WjbMeta;
  routineState?: WjbRoutineState;   // 可选，首次访问时惰性初始化
}

export const STORAGE_KEY = "wuxianjinbu-data-v1";
export const SCHEMA_VERSION = "wuxianjinbu-v1" as const;

/* ----- 工具：当前时间 ISO ----- */
export function nowIso(): string {
  return new Date().toISOString();
}

/**
 * 工具：本地日期 key（YYYY-MM-DD，按本地时区）
 *
 * 修复 #2（M1-New.2 P1）：禁止用 toISOString().slice(0,10) 当本地"今天"。
 * UTC 与本地差 ≥1 时区时（中国 UTC+8），晚上读 toISOString 会返回明天的 UTC 日期，
 * 导致今日任务 / 今日时间块 / 今日进度跨天错乱。
 * 所有需要"本地今天/某日"判断的地方一律走本工具。
 */
export function localDateKey(d: Date = new Date()): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

/* ----- 工具：随机 id ----- */
export function uid(prefix: string): string {
  return `${prefix}_${Math.random().toString(36).slice(2, 10)}${Date.now().toString(36)}`;
}
