import { T } from "../i18n";
import { ICON } from "./icons";
import type { Priority, WjbTask } from "../data/types";
import {
  findProject,
  findTask,
  updateTask,
  deleteTask,
  completeTask,
  uncompleteTask,
  priorityLabel,
  priorityClass,
} from "../data/actions";
import { storeSnapshot } from "../data/selectors";
import { renderAiSuggestionCard } from "./aiSuggestionCard";

/**
 * 任务详情抽屉 · M1-New.2 接通真实编辑保存 + 底部固定 footer
 *
 * 交互心智（PRD §9.4.3 + 交互规范 §6）：
 *   - 抽屉打开 → app.is-detail-open → scrim 显示 + 抽屉 translateX(0) 进入 → 覆盖右栏
 *   - 关闭方式：× / scrim / Esc / footer「关闭」
 *
 * 编辑保存策略：
 *   - 标题：blur 自动保存
 *   - 描述：blur 自动保存
 *   - 优先级：下拉切换 → 立即保存
 *   - 项目：下拉切换 → 立即保存
 *   - 截止日期：date input change → 立即保存
 *   - footer「保存」按钮：仅做反馈提示（每次编辑已自动保存）
 *   - footer「删除」：二次确认按钮（首次显示「确认删除」红色）
 *   - footer「关闭」：关抽屉
 */

let _currentId: string | null = null;
let _deleteConfirming = false;
let _onAfterChange: (() => void) | null = null;

export function setDrawerAfterChange(cb: () => void): void {
  _onAfterChange = cb;
}

export function renderTaskDetailDrawer(): string {
  return `
    <div class="pms-scrim" data-act="close-drawer" aria-hidden="true"></div>
    <aside class="pms-task-detail-drawer" id="pms-task-detail-drawer" role="dialog" aria-modal="false" aria-label="${T.drawer.title}">
      <div class="pms-task-detail-drawer-header">
        <div class="pms-task-detail-drawer-title" id="pms-drawer-title">${T.drawer.title}</div>
        <button class="pms-icon-button" data-act="close-drawer" type="button" title="${T.drawer.close}">
          ${ICON.close}
        </button>
      </div>
      <div class="pms-task-detail-drawer-body" id="pms-drawer-body">
        <div class="pms-empty-state">
          <div class="pms-empty-state-title">${T.drawer.empty}</div>
        </div>
      </div>
      <div class="pms-task-detail-drawer-footer" id="pms-drawer-footer" style="display:none">
        <button class="pms-text-button" data-act="drawer-toggle-done" type="button" id="pms-drawer-toggle-done"></button>
        <div class="pms-drawer-footer-spacer"></div>
        <button class="pms-danger-button is-secondary" data-act="drawer-delete" type="button" id="pms-drawer-delete">${T.buttons.danger}</button>
        <button class="pms-secondary-button" data-act="close-drawer" type="button">${T.drawer.close}</button>
        <button class="pms-primary-button" data-act="drawer-save" type="button">${T.drawer.saved}</button>
      </div>
    </aside>
  `;
}

export function openDrawer(taskId: string): void {
  const t = findTask(taskId);
  if (!t) return;
  _currentId = taskId;
  _deleteConfirming = false;

  const titleEl = document.getElementById("pms-drawer-title");
  const bodyEl  = document.getElementById("pms-drawer-body");
  const footEl  = document.getElementById("pms-drawer-footer");
  if (!titleEl || !bodyEl || !footEl) return;

  titleEl.textContent = t.title || T.drawer.title;
  bodyEl.innerHTML    = renderDrawerBody(t);
  footEl.style.display = "flex";
  refreshFooter(t);

  document.querySelector(".pms-app-m1")?.classList.add("is-detail-open");
  bindFieldEvents();
  bindFooterEventsOnce();  // 修复 #1：footer DOM 是静态的，跨多次打开不应重绑
}

/**
 * 修复 #1（M1-New.2 P1）：footer 事件只绑定一次。
 * footer DOM 在 renderTaskDetailDrawer 时建好就不再重建；
 * 之前 openDrawer 每次都 bindFooterEvents → 多次打开后 click 监听叠加 → 状态来回反转。
 */
let _footerBound = false;
function bindFooterEventsOnce(): void {
  if (_footerBound) return;
  _footerBound = true;
  bindFooterEvents();
}

export function closeDrawer(): void {
  document.querySelector(".pms-app-m1")?.classList.remove("is-detail-open");
  _currentId = null;
  _deleteConfirming = false;
  const foot = document.getElementById("pms-drawer-footer");
  if (foot) foot.style.display = "none";
}

/* ----- 渲染抽屉 body ----- */

function renderDrawerBody(t: WjbTask): string {
  const proj = findProject(t.projectId);
  const allProjects = storeSnapshot().projects;
  const statusLabel = t.status === "done" ? T.status.done : T.status.notStarted;

  return `
    <div class="pms-task-detail-field">
      <div class="pms-task-detail-field-label">${T.drawer.title}</div>
      <input
        type="text"
        class="pms-text-field"
        id="pms-drawer-input-title"
        value="${escAttr(t.title)}"
        aria-label="${T.drawer.title}"
      />
    </div>

    <div class="pms-task-detail-attr-row">
      <div class="pms-task-detail-field">
        <div class="pms-task-detail-field-label">${T.drawer.project}</div>
        <select class="pms-text-field" id="pms-drawer-select-project" aria-label="${T.drawer.project}">
          <option value=""${proj ? "" : " selected"}>无（${T.sidebar.nav.inbox}）</option>
          ${allProjects.map((p) => `<option value="${escAttr(p.id)}"${proj?.id === p.id ? " selected" : ""}>${esc(p.name)}</option>`).join("")}
        </select>
      </div>
      <div class="pms-task-detail-field">
        <div class="pms-task-detail-field-label">${T.drawer.priority}</div>
        <select class="pms-text-field" id="pms-drawer-select-priority" aria-label="${T.drawer.priority}">
          ${(["P1","P2","P3","P4"] as Priority[]).map((p) => `<option value="${p}"${t.priority === p ? " selected" : ""}>${p} · ${priorityLabel(p)}</option>`).join("")}
        </select>
      </div>
      <div class="pms-task-detail-field">
        <div class="pms-task-detail-field-label">${T.drawer.status}</div>
        <div class="pms-task-detail-field-value">
          <span class="pms-pri-badge ${priorityClass(t.priority)}">${statusLabel}</span>
        </div>
      </div>
      <div class="pms-task-detail-field">
        <div class="pms-task-detail-field-label">${T.drawer.due}</div>
        <input
          type="date"
          class="pms-text-field"
          id="pms-drawer-input-due"
          value="${escAttr(t.dueDate ?? "")}"
          aria-label="${T.drawer.due}"
        />
      </div>
    </div>

    <div class="pms-task-detail-field">
      <div class="pms-task-detail-field-label">${T.drawer.description}</div>
      <textarea class="pms-textarea" id="pms-drawer-input-desc" placeholder="为这条任务补充背景或步骤…">${esc(t.description ?? "")}</textarea>
    </div>

    <div class="pms-task-detail-field">
      <div class="pms-task-detail-field-label">${T.drawer.aiSection}</div>
      ${renderAiSuggestionCard()}
    </div>

    <div class="pms-task-detail-field" id="pms-drawer-save-status" style="display:none">
      <div class="pms-task-detail-field-value" id="pms-drawer-save-text" style="color:var(--text-3);font-size:var(--fs-meta)"></div>
    </div>
  `;
}

/* ----- footer 渲染：根据当前任务 status 切换「标记完成 / 取消完成」 ----- */
function refreshFooter(t: WjbTask): void {
  const toggleBtn = document.getElementById("pms-drawer-toggle-done");
  const deleteBtn = document.getElementById("pms-drawer-delete");
  if (toggleBtn) {
    toggleBtn.textContent = t.status === "done" ? "取消完成" : "标记完成";
  }
  if (deleteBtn) {
    deleteBtn.textContent = _deleteConfirming ? "确认删除" : T.buttons.danger;
    deleteBtn.classList.toggle("is-secondary", !_deleteConfirming);
  }
}

/* ----- 字段编辑事件：onblur / change 自动保存 ----- */
function bindFieldEvents(): void {
  const titleEl = document.getElementById("pms-drawer-input-title") as HTMLInputElement | null;
  const descEl  = document.getElementById("pms-drawer-input-desc")  as HTMLTextAreaElement | null;
  const projEl  = document.getElementById("pms-drawer-select-project") as HTMLSelectElement | null;
  const priEl   = document.getElementById("pms-drawer-select-priority") as HTMLSelectElement | null;
  const dueEl   = document.getElementById("pms-drawer-input-due") as HTMLInputElement | null;

  const onSave = () => flashSaveStatus(T.drawer.saveNotice);

  titleEl?.addEventListener("blur", () => {
    if (!_currentId) return;
    const v = titleEl.value.trim();
    if (!v) { titleEl.value = findTask(_currentId)?.title ?? ""; return; }
    updateTask(_currentId, { title: v });
    onSave();
    // 同步抽屉标题
    const h = document.getElementById("pms-drawer-title");
    if (h) h.textContent = v;
    _onAfterChange?.();
  });

  descEl?.addEventListener("blur", () => {
    if (!_currentId) return;
    updateTask(_currentId, { description: descEl.value });
    onSave();
    _onAfterChange?.();
  });

  projEl?.addEventListener("change", () => {
    if (!_currentId) return;
    const v = projEl.value || null;
    updateTask(_currentId, { projectId: v });
    onSave();
    _onAfterChange?.();
  });

  priEl?.addEventListener("change", () => {
    if (!_currentId) return;
    updateTask(_currentId, { priority: priEl.value as Priority });
    onSave();
    _onAfterChange?.();
  });

  dueEl?.addEventListener("change", () => {
    if (!_currentId) return;
    updateTask(_currentId, { dueDate: dueEl.value || undefined });
    onSave();
    _onAfterChange?.();
  });
}

/* ----- footer 事件 ----- */
function bindFooterEvents(): void {
  document.getElementById("pms-drawer-toggle-done")?.addEventListener("click", () => {
    if (!_currentId) return;
    const t = findTask(_currentId);
    if (!t) return;
    const next = t.status === "done" ? uncompleteTask(_currentId) : completeTask(_currentId);
    if (next) {
      refreshFooter(next);
      flashSaveStatus(next.status === "done" ? "已标记为完成" : "已恢复为未完成");
    }
    _onAfterChange?.();
  });

  document.getElementById("pms-drawer-delete")?.addEventListener("click", () => {
    if (!_currentId) return;
    if (!_deleteConfirming) {
      _deleteConfirming = true;
      const t = findTask(_currentId);
      if (t) refreshFooter(t);
      // 5 秒未确认则复原
      setTimeout(() => {
        if (!_deleteConfirming) return;
        _deleteConfirming = false;
        const tt = _currentId ? findTask(_currentId) : null;
        if (tt) refreshFooter(tt);
      }, 5000);
      return;
    }
    // 二次点击 → 真删
    deleteTask(_currentId);
    _currentId = null;
    _deleteConfirming = false;
    closeDrawer();
    _onAfterChange?.();
  });

  document.querySelectorAll('[data-act="drawer-save"]').forEach((el) => {
    el.addEventListener("click", () => {
      // 字段已经 onblur 自动保存，按钮仅给视觉反馈
      // 主动触发 blur 以保存任何处于焦点的字段
      (document.activeElement as HTMLElement | null)?.blur();
      flashSaveStatus(T.drawer.saved);
    });
  });
}

/* ----- 保存提示一闪 ----- */
let _saveTimer: number | null = null;
function flashSaveStatus(text: string): void {
  const wrap = document.getElementById("pms-drawer-save-status");
  const txt  = document.getElementById("pms-drawer-save-text");
  if (!wrap || !txt) return;
  txt.textContent = text;
  wrap.style.display = "block";
  if (_saveTimer) window.clearTimeout(_saveTimer);
  _saveTimer = window.setTimeout(() => {
    wrap.style.display = "none";
  }, 1600);
}

/* ----- utils ----- */
function esc(s: string): string {
  return (s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
}
function escAttr(s: string): string { return esc(s); }
