/**
 * 任务池面板 · M1-New.3R
 *
 * 纵向列表，固定 228px，60px 行高
 * 筛选：今日 / 高优 / 到期 / 未排 / 已部分 / 逾期
 * 拖拽：HTML5 DnD（draggable=true）→ 时间轴 drop 生成时间块
 */

import { T } from "../i18n";
import type { WjbTask } from "../data/types";
import { localDateKey } from "../data/types";
import { findProject } from "../data/actions";
import {
  poolTodayTasks,
  poolHighPriorityTasks,
  poolUpcomingDeadlineTasks,
  poolUnscheduledTasks,
  poolPartialTasks,
  poolOverdueTasks,
} from "../data/selectors";

/* ── 面板状态 ─────────────────────────────────────────── */

type FilterKey = "today" | "highPri" | "upcoming" | "unscheduled" | "partial" | "overdue";

let _filter: FilterKey = "today";
let _collapsed = false;

export function getPoolFilter(): FilterKey { return _filter; }
export function setPoolFilter(f: FilterKey): void { _filter = f; }
export function getPoolCollapsed(): boolean { return _collapsed; }
export function togglePoolCollapsed(): void { _collapsed = !_collapsed; }

/* ── 渲染 ─────────────────────────────────────────────── */

export function renderTaskPool(): string {
  if (_collapsed) return renderCollapsed();

  const tasks = _getFilteredTasks();
  const unscheduledCount = poolUnscheduledTasks().length;

  const filterBtns = (Object.keys(T.pool.filters) as FilterKey[]).map((k) => `
    <button class="atp-filter${_filter === k ? " is-active" : ""}"
      data-act="pool-filter" data-value="${k}" type="button">
      ${esc(T.pool.filters[k])}
    </button>`).join("");

  return `
<div class="pms-taskpool" id="pms-taskpool">
  <div class="atp-header">
    <div class="atp-title-row">
      <div class="atp-title">${esc(T.pool.title)}</div>
      <div class="atp-count">· 未安排 ${unscheduledCount}</div>
      <button class="atp-collapse" data-act="pool-collapse" type="button">&#8249; ${esc(T.pool.collapse)}</button>
    </div>
    <div class="atp-filters">${filterBtns}</div>
  </div>
  <div class="atp-list" id="pms-pool-list">
    ${tasks.length === 0
      ? `<div class="atp-empty">${esc(T.pool.noTasks)}<br><span class="atp-empty-hint">${esc(T.pool.noTasksHint)}</span></div>`
      : tasks.map(renderPoolRow).join("")
    }
  </div>
</div>`;
}

function renderCollapsed(): string {
  return `
<div class="pms-taskpool pms-taskpool-collapsed" id="pms-taskpool">
  <button class="atp-expand-btn" data-act="pool-collapse" type="button"
    title="${esc(T.pool.expand)}">
    <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
      <path d="M4 2l4 4-4 4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
    </svg>
  </button>
</div>`;
}

function renderPoolRow(t: WjbTask): string {
  const proj = findProject(t.projectId);
  const projName = proj ? proj.name : T.sidebar.nav.inbox;
  const priColor = priDotColor(t.priority);
  const statusLabel = _scheduleStatusLabel(t);
  const statusCls = _scheduleStatusCls(t);
  const isOverdue = t.dueDate && t.dueDate < localDateKey();
  const isArranged = t.scheduleStatus === "partial" || t.scheduleStatus === "scheduled";

  // 截止日期文案
  let dueLabel = "";
  let dueCls = "";
  if (t.dueDate) {
    const today = localDateKey();
    if (t.dueDate < today) {
      dueLabel = `逾期 ${_friendlyDate(t.dueDate, today)}`;
      dueCls = "tp-due-late";
    } else if (t.dueDate === today) {
      dueLabel = "截止今日";
      dueCls = "tp-due-near";
    } else {
      dueLabel = `截止 ${_friendlyDate(t.dueDate, today)}`;
    }
  }

  // AI 预估工时
  const aiEstLabel = t.aiEstimatedMinutes
    ? `AI 预估 ${_durationShort(t.aiEstimatedMinutes)}`
    : "";

  return `
<div class="tp-row${isOverdue ? " tp-row-overdue" : ""}"
     data-task-id="${esc(t.id)}"
     draggable="true"
     title="${esc(t.title)}">
  <div class="tp-row-line1">
    <div class="tp-pri" style="background:${priColor}"></div>
    <div class="tp-title">${esc(t.title)}</div>
    <div class="tp-status ${statusCls}">${esc(statusLabel)}</div>
    <button class="tp-arrange"
      data-act="${isArranged ? "pool-rearrange" : "pool-arrange"}"
      data-task-id="${esc(t.id)}"
      type="button">
      ${esc(isArranged ? T.pool.rearrange : T.pool.arrange)}
    </button>
  </div>
  <div class="tp-row-line2">
    ${proj ? `<span class="tp-proj" style="color:var(${proj.colorToken})">${esc(projName)}</span>` : `<span class="tp-proj">${esc(projName)}</span>`}
    ${dueLabel ? `<span>·</span><span class="tp-due ${dueCls}">${esc(dueLabel)}</span>` : ""}
    ${aiEstLabel ? `<span>·</span><span class="tp-ai-est">
      <svg width="9" height="9" viewBox="0 0 10 10" fill="none" class="tp-ai-icon">
        <path d="M5 1L6.2 3.9H9.5L6.8 5.9 7.7 9 5 7.2 2.3 9 3.2 5.9.5 3.9H3.8L5 1Z"
              fill="var(--accent)" opacity=".6"/>
      </svg>
      ${esc(aiEstLabel)}</span>` : ""}
  </div>
</div>`;
}

/* ── 拖拽数据 ─────────────────────────────────────────── */

/** 绑定任务池行的 dragstart 事件（渲染后调用） */
export function bindPoolDragEvents(container: HTMLElement): void {
  container.addEventListener("dragstart", (e) => {
    const row = (e.target as HTMLElement).closest<HTMLElement>("[data-task-id]");
    if (!row?.dataset.taskId) { e.preventDefault(); return; }
    e.dataTransfer?.setData("text/plain", row.dataset.taskId);
    row.classList.add("tp-dragging");
  });
  container.addEventListener("dragend", (e) => {
    const row = (e.target as HTMLElement).closest<HTMLElement>("[data-task-id]");
    row?.classList.remove("tp-dragging");
    document.querySelectorAll(".tl-drop-indicator").forEach((el) => el.remove());
  });
}

/* ── 筛选 ──────────────────────────────────────────────── */

function _getFilteredTasks(): WjbTask[] {
  switch (_filter) {
    case "today":       return poolTodayTasks();
    case "highPri":     return poolHighPriorityTasks();
    case "upcoming":    return poolUpcomingDeadlineTasks();
    case "unscheduled": return poolUnscheduledTasks();
    case "partial":     return poolPartialTasks();
    case "overdue":     return poolOverdueTasks();
    default:            return poolTodayTasks();
  }
}

/* ── 辅助 ──────────────────────────────────────────────── */

function priDotColor(p: WjbTask["priority"]): string {
  return { P1: "var(--danger)", P2: "var(--warning)", P3: "var(--text-4)", P4: "var(--text-4)" }[p];
}

function _scheduleStatusLabel(t: WjbTask): string {
  const m = T.pool.statusLabel;
  switch (t.scheduleStatus) {
    case "partial":     return m.partial;
    case "scheduled":   return m.scheduled;
    case "done":        return m.done;
    case "overdue":     return m.overdue;
    default:            return m.unscheduled;
  }
}

function _scheduleStatusCls(t: WjbTask): string {
  switch (t.scheduleStatus) {
    case "partial":     return "tp-status-partial";
    case "scheduled":   return "tp-status-scheduled";
    case "done":        return "tp-status-done";
    case "overdue":     return "tp-status-overdue";
    default:            return "tp-status-unscheduled";
  }
}

function _friendlyDate(dateKey: string, today: string): string {
  const [ty, tm, td] = today.split("-").map(Number);
  const [ky, km, kd] = dateKey.split("-").map(Number);
  const diffMs = new Date(ky, km - 1, kd).getTime() - new Date(ty, tm - 1, td).getTime();
  const diff = Math.round(diffMs / 86400000);
  if (diff === 0) return "今日";
  if (diff === -1) return "昨日";
  if (diff === 1) return "明日";
  return `${km}月${kd}日`;
}

function _durationShort(mins: number): string {
  if (mins < 60) return `${mins}分`;
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return m === 0 ? `${h}h` : `${h}h${m}分`;
}

function esc(s: string): string {
  return (s ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!,
  );
}
