import { T } from "../i18n";
import { ICON } from "./icons";

/**
 * 基础输入预览（组件预览页用）
 * 不接真实表单逻辑，仅展示视觉与焦点态。
 */
export function renderInputShowcase(): string {
  return `
    <div class="pms-preview-row">
      <div class="pms-preview-row-label">单行输入</div>
      <input class="pms-text-field" type="text" placeholder="${T.preview.inputPlaceholder}" style="max-width:320px" />
    </div>

    <div class="pms-preview-row">
      <div class="pms-preview-row-label">搜索框</div>
      <input class="pms-text-field" type="text" placeholder="${T.preview.searchPlaceholder}" style="max-width:320px" />
    </div>

    <div class="pms-preview-row">
      <div class="pms-preview-row-label">多行文本</div>
      <textarea class="pms-textarea" placeholder="${T.preview.textareaPlaceholder}" style="max-width:520px"></textarea>
    </div>

    <div class="pms-preview-row">
      <div class="pms-preview-row-label">日期选择</div>
      <div class="pms-date-picker" tabindex="0">
        ${ICON.calendar}
        <span>${T.preview.selectDate}</span>
      </div>
    </div>

    <div class="pms-preview-row">
      <div class="pms-preview-row-label">禁用态</div>
      <input class="pms-text-field" type="text" value="此项不可编辑" disabled style="max-width:320px" />
    </div>
  `;
}
