/**
 * 时间工具函数库 · M1-New.3R
 *
 * 供时间轴渲染、任务池筛选、跨日判断使用。
 * 全部基于本地时区（不用 UTC）。
 */

/** 某天的开始时刻（00:00:00.000 本地时间，返回 Date） */
export function dayStart(dateKey: string): Date {
  const [y, m, d] = dateKey.split("-").map(Number);
  const dt = new Date(y, m - 1, d, 0, 0, 0, 0);
  return dt;
}

/** 某天的结束时刻（23:59:59.999 本地时间，返回 Date） */
export function dayEnd(dateKey: string): Date {
  const [y, m, d] = dateKey.split("-").map(Number);
  return new Date(y, m - 1, d, 23, 59, 59, 999);
}

/**
 * 时间块是否在某天有重叠（新版今日筛选规则）
 * block.start < dayEnd && block.end > dayStart
 */
export function blockOverlapsDay(
  start: string,
  end: string,
  dateKey: string,
): boolean {
  const bs = new Date(start).getTime();
  const be = new Date(end).getTime();
  const ds = dayStart(dateKey).getTime();
  const de = dayEnd(dateKey).getTime();
  return bs < de && be > ds;
}

/**
 * 从当天 00:00 起算的分钟数（用于像素定位）
 * 对于跨日时间块，使用当天切片的起始点（不超过 0，不超过 24*60）
 */
export function minutesFromDayStart(isoDatetime: string, dateKey: string): number {
  const dt = new Date(isoDatetime);
  const ds = dayStart(dateKey);
  const diffMs = dt.getTime() - ds.getTime();
  const mins = Math.floor(diffMs / 60000);
  return Math.max(0, Math.min(mins, 24 * 60));
}

/** 时间块在某天内的持续分钟（跨日则截断到当天） */
export function blockDurationMinutes(
  start: string,
  end: string,
  dateKey: string,
): number {
  const startMins = minutesFromDayStart(start, dateKey);
  const be = new Date(end);
  const de = dayEnd(dateKey);
  const effectiveEnd = be.getTime() < de.getTime() ? be : de;
  const endMins = Math.floor(
    (effectiveEnd.getTime() - dayStart(dateKey).getTime()) / 60000,
  );
  return Math.max(0, Math.min(endMins, 24 * 60) - startMins);
}

/** 是否为跨日时间块（end 和 start 不在同一天） */
export function isCrossDay(start: string, end: string): boolean {
  const s = new Date(start);
  const e = new Date(end);
  return (
    s.getFullYear() !== e.getFullYear() ||
    s.getMonth() !== e.getMonth() ||
    s.getDate() !== e.getDate()
  );
}

/**
 * 跨日状态
 * "same_day"     — 同一天
 * "cross_start"  — start 在当日，end 在次日（或更后）
 * "cross_end"    — start 在前日（或更前），end 在当日
 */
export function crossDayState(
  start: string,
  end: string,
  dateKey: string,
): "same_day" | "cross_start" | "cross_end" {
  const sKey = localDateKeyFromIso(start);
  const eKey = localDateKeyFromIso(end);
  if (sKey === dateKey && eKey === dateKey) return "same_day";
  if (sKey === dateKey) return "cross_start";
  return "cross_end";
}

/** ISO datetime → 本地 YYYY-MM-DD */
export function localDateKeyFromIso(iso: string): string {
  const d = new Date(iso);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

/** 格式化时间 HH:MM（本地时间） */
export function fmtTime(iso: string): string {
  const d = new Date(iso);
  return `${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

/** 格式化日期 YYYY-MM-DD */
export function fmtDate(iso: string): string {
  return localDateKeyFromIso(iso);
}

/** 当前时间分钟偏移（从今天 00:00 算，超出 0-1440 范围则截断） */
export function currentMinuteOffset(): number {
  const now = new Date();
  return now.getHours() * 60 + now.getMinutes();
}

/** 将 YYYY-MM-DD + HH:MM 合成 ISO 字符串（本地时间） */
export function composeDatetime(dateKey: string, hhmm: string): string {
  const [h, m] = hhmm.split(":").map(Number);
  const [y, mo, d] = dateKey.split("-").map(Number);
  const dt = new Date(y, mo - 1, d, h, m, 0, 0);
  return dt.toISOString();
}

/** 显示"今天"/"明天"/"后天"/"MM月DD日"等友好日期 */
export function friendlyDate(dateKey: string, todayKey: string): string {
  const [ty, tm, td] = todayKey.split("-").map(Number);
  const [ky, km, kd] = dateKey.split("-").map(Number);
  const todayMs = new Date(ty, tm - 1, td).getTime();
  const keyMs = new Date(ky, km - 1, kd).getTime();
  const diffDays = Math.round((keyMs - todayMs) / 86400000);
  if (diffDays === 0) return "今天";
  if (diffDays === 1) return "明天";
  if (diffDays === 2) return "后天";
  if (diffDays === -1) return "昨天";
  const d = new Date(ky, km - 1, kd);
  return `${d.getMonth() + 1}月${d.getDate()}日`;
}

/** 本周五的 dateKey */
export function thisWeekFriday(todayKey: string): string {
  const [y, m, d] = todayKey.split("-").map(Number);
  const dt = new Date(y, m - 1, d);
  const dow = dt.getDay(); // 0=Sun
  const daysUntilFri = dow === 0 ? 5 : (5 - dow + 7) % 7;
  const fri = new Date(y, m - 1, d + (daysUntilFri === 0 ? 7 : daysUntilFri));
  return `${fri.getFullYear()}-${String(fri.getMonth() + 1).padStart(2, "0")}-${String(fri.getDate()).padStart(2, "0")}`;
}

/** 下周一的 dateKey */
export function nextMonday(todayKey: string): string {
  const [y, m, d] = todayKey.split("-").map(Number);
  const dt = new Date(y, m - 1, d);
  const dow = dt.getDay();
  const daysUntilMon = dow === 0 ? 1 : (8 - dow) % 7 || 7;
  const mon = new Date(y, m - 1, d + daysUntilMon);
  return `${mon.getFullYear()}-${String(mon.getMonth() + 1).padStart(2, "0")}-${String(mon.getDate()).padStart(2, "0")}`;
}

/** dateKey 加 N 天 */
export function addDays(dateKey: string, n: number): string {
  const [y, m, d] = dateKey.split("-").map(Number);
  const dt = new Date(y, m - 1, d + n);
  return `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, "0")}-${String(dt.getDate()).padStart(2, "0")}`;
}

/** 分钟数转 HH:MM 字符串 */
export function minutesToHhmm(mins: number): string {
  const h = Math.floor(mins / 60) % 24;
  const m = mins % 60;
  return `${pad(h)}:${pad(m)}`;
}

/** HH:MM → 当天分钟数 */
export function hhmmToMinutes(hhmm: string): number {
  const [h, m] = hhmm.split(":").map(Number);
  return (h || 0) * 60 + (m || 0);
}

/** 时长文案（分钟 → "30分钟" / "1小时30分钟"） */
export function durationLabel(mins: number): string {
  if (mins < 60) return `${mins}分钟`;
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return m === 0 ? `${h}小时` : `${h}小时${m}分钟`;
}

/** 吸附到最近 N 分钟 */
export function snapMinutes(mins: number, snap = 15): number {
  return Math.round(mins / snap) * snap;
}

/** 获取某月日历网格（6周 × 7天，含上月/下月补位） */
export function getCalendarDays(year: number, month: number): {
  key: string;
  date: number;
  isCurrentMonth: boolean;
}[] {
  const firstDay = new Date(year, month - 1, 1);
  const lastDay = new Date(year, month, 0);
  // 周一为第一天
  let startDow = firstDay.getDay(); // 0=Sun
  startDow = startDow === 0 ? 6 : startDow - 1; // 转成周一=0

  const days: { key: string; date: number; isCurrentMonth: boolean }[] = [];

  // 上月补位
  for (let i = startDow - 1; i >= 0; i--) {
    const d = new Date(year, month - 1, -i);
    days.push({ key: toKey(d), date: d.getDate(), isCurrentMonth: false });
  }
  // 本月
  for (let d = 1; d <= lastDay.getDate(); d++) {
    const dt = new Date(year, month - 1, d);
    days.push({ key: toKey(dt), date: d, isCurrentMonth: true });
  }
  // 下月补位（凑满 42 格）
  let next = 1;
  while (days.length < 42) {
    const d = new Date(year, month, next++);
    days.push({ key: toKey(d), date: d.getDate(), isCurrentMonth: false });
  }
  return days;
}

function toKey(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function pad(n: number): string {
  return String(n).padStart(2, "0");
}
