/**
 * 时间轴日期标题选择器 · M1-New.3R（P0 修复）
 *
 * 点击时间轴日期标题（data-act="tl-open-date-picker"）打开。
 * 自定义日历，不用浏览器原生 input[type=date]。
 *
 * 架构与 timeBlockPopover / reviewFlyout 一致：
 *   - 挂在 document.body（#app 外）
 *   - 事件由 appShell 的 document 级委托分发到 handleTimelineDatePickerClick
 *   - 确认才改日期；取消 / 点击外部 / ESC 不改日期
 */

import { T } from "../i18n";
import { localDateKey } from "../data/types";
import {
  getCalendarDays,
  thisWeekFriday,
  nextMonday,
  addDays,
} from "../lib/timeUtils";

const PANEL_ID = "pms-tl-datepicker";
const SCRIM_ID = "pms-tl-datepicker-scrim";

interface State {
  selected: string;   // YYYY-MM-DD（草稿，确认才生效）
  viewYear: number;
  viewMonth: number;  // 1-12
  onConfirm: (dateKey: string) => void;
}

let _state: State | null = null;

export function isTimelineDatePickerOpen(): boolean {
  return !!document.getElementById(PANEL_ID);
}

/** 打开（anchorEl = 日期标题元素，用于定位） */
export function openTimelineDatePicker(
  currentDate: string,
  anchorEl: HTMLElement,
  onConfirm: (dateKey: string) => void,
): void {
  closeTimelineDatePicker();
  const [y, m] = currentDate.split("-").map(Number);
  _state = { selected: currentDate, viewYear: y, viewMonth: m, onConfirm };

  const scrim = document.createElement("div");
  scrim.id = SCRIM_ID;
  scrim.style.cssText = "position:fixed;inset:0;z-index:560;";
  scrim.setAttribute("data-act", "close-tldp");
  document.body.appendChild(scrim);

  const panel = document.createElement("div");
  panel.id = PANEL_ID;
  panel.className = "tldp-panel";
  panel.innerHTML = _buildHtml(_state);
  document.body.appendChild(panel);

  _position(panel, anchorEl);
}

export function closeTimelineDatePicker(): void {
  document.getElementById(PANEL_ID)?.remove();
  document.getElementById(SCRIM_ID)?.remove();
  _state = null;
}

function _repaint(): void {
  if (!_state) return;
  const panel = document.getElementById(PANEL_ID);
  if (panel) panel.innerHTML = _buildHtml(_state);
}

function _position(panel: HTMLElement, anchor: HTMLElement): void {
  const r = anchor.getBoundingClientRect();
  const pw = 280;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  let left = r.left;
  if (left + pw > vw - 8) left = vw - pw - 8;
  if (left < 8) left = 8;
  let top = r.bottom + 6;
  const ph = panel.offsetHeight || 360;
  if (top + ph > vh - 8) top = Math.max(8, r.top - ph - 6);
  panel.style.cssText = `position:fixed;left:${left}px;top:${top}px;width:${pw}px;z-index:561;`;
}

function _buildHtml(s: State): string {
  const today = localDateKey();
  const days = getCalendarDays(s.viewYear, s.viewMonth);
  const shortcuts = [
    { k: today, l: T.datePicker.today },
    { k: addDays(today, 1), l: T.datePicker.tomorrow },
    { k: thisWeekFriday(today), l: T.datePicker.thisWeekFriday },
    { k: nextMonday(today), l: T.datePicker.nextMonday },
  ];
  const cells = days.map(({ key, date, isCurrentMonth }) => {
    const cls = [
      "dp-cell",
      key === today ? "dp-today" : "",
      key === s.selected ? "dp-selected" : "",
      !isCurrentMonth ? "dp-other" : "",
    ].filter(Boolean).join(" ");
    return `<div class="${cls}" data-act="tldp-pick" data-value="${esc(key)}">${date}</div>`;
  }).join("");

  return `
<div class="dp-header">
  <button class="dp-nav-btn" data-act="tldp-prev" type="button">&#8249;</button>
  <div class="dp-title">${s.viewYear}年${s.viewMonth}月</div>
  <button class="dp-nav-btn" data-act="tldp-next" type="button">&#8250;</button>
</div>
<div class="dp-shortcuts">
  ${shortcuts.map((sc) => `<button class="dp-shortcut${sc.k === s.selected ? " dp-sc-active" : ""}"
    data-act="tldp-pick" data-value="${esc(sc.k)}" type="button">${esc(sc.l)}</button>`).join("")}
</div>
<div class="dp-weekdays">${T.datePicker.weekdays.map((w) => `<div class="dp-wd">${esc(w)}</div>`).join("")}</div>
<div class="dp-grid">${cells}</div>
<div class="dp-footer">
  <button class="dp-cancel-btn" data-act="close-tldp" type="button">${esc(T.datePicker.cancel)}</button>
  <button class="dp-confirm-btn" data-act="tldp-confirm" type="button">${esc(T.datePicker.confirm)}</button>
</div>`;
}

/** appShell document 委托调用 */
export function handleTimelineDatePickerClick(act: string, target: HTMLElement): void {
  if (!_state) return;
  switch (act) {
    case "close-tldp":
      closeTimelineDatePicker();
      return;
    case "tldp-prev":
      _state.viewMonth -= 1;
      if (_state.viewMonth < 1) { _state.viewMonth = 12; _state.viewYear -= 1; }
      _repaint();
      return;
    case "tldp-next":
      _state.viewMonth += 1;
      if (_state.viewMonth > 12) { _state.viewMonth = 1; _state.viewYear += 1; }
      _repaint();
      return;
    case "tldp-pick": {
      const v = target.dataset.value;
      if (v) { _state.selected = v; _repaint(); }
      return;
    }
    case "tldp-confirm": {
      const chosen = _state.selected;
      const cb = _state.onConfirm;
      closeTimelineDatePicker();
      cb(chosen);
      return;
    }
  }
}

function esc(str: string): string {
  return (str ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!,
  );
}
