/**
 * 复盘小浮层 · M1-New.3R
 * 仅在时间块 status=done 时触发
 * 存储：timeBlock.reviewNote
 */

import { T } from "../i18n";
import { findTimeBlock, saveReviewNote } from "../data/actions";
import { fmtTime } from "../lib/timeUtils";

let _currentBlockId: string | null = null;

const FLYOUT_ID = "pms-review-flyout";

/** 打开复盘浮层（锚定到触发按钮旁） */
export function openReviewFlyout(blockId: string, anchorEl: HTMLElement): void {
  closeReviewFlyout();
  _currentBlockId = blockId;

  const block = findTimeBlock(blockId);
  if (!block) return;

  const flyout = document.createElement("div");
  flyout.id = FLYOUT_ID;
  flyout.className = "rf-wrap";
  flyout.innerHTML = _buildHtml(block.title, block.start, block.end, block.reviewNote ?? "");
  document.body.appendChild(flyout);
  _positionFlyout(flyout, anchorEl);

  // 聚焦 textarea
  setTimeout(() => {
    flyout.querySelector<HTMLTextAreaElement>(".rf-textarea")?.focus();
  }, 50);

  // 点击外部关闭
  setTimeout(() => {
    document.addEventListener("click", _outsideClick, { once: false, capture: true });
  }, 0);
}

export function closeReviewFlyout(): void {
  document.getElementById(FLYOUT_ID)?.remove();
  document.removeEventListener("click", _outsideClick, true);
  _currentBlockId = null;
}

export function isReviewFlyoutOpen(): boolean {
  return !!document.getElementById(FLYOUT_ID);
}

function _buildHtml(title: string, start: string, end: string, note: string): string {
  return `
<div class="rf-head">
  <div class="rf-icon">
    <svg width="10" height="10" viewBox="0 0 10 10" fill="none">
      <path d="M5 1L6.2 3.9H9.5L6.8 5.9 7.7 9 5 7.2 2.3 9 3.2 5.9.5 3.9H3.8L5 1Z"
            fill="var(--accent)" opacity=".8"/>
    </svg>
  </div>
  <div class="rf-title">${esc(T.review.title)}</div>
  <button class="rf-close" data-act="close-review" type="button">&#x2715;</button>
</div>
<div class="rf-block-name">${esc(title)}</div>
<div class="rf-block-time">${esc(fmtTime(start))} — ${esc(fmtTime(end))}</div>
<textarea class="rf-textarea" placeholder="${esc(T.review.placeholder)}"
  rows="4">${esc(note)}</textarea>
<div class="rf-ai-hint">
  <svg width="10" height="10" viewBox="0 0 10 10" fill="none">
    <path d="M5 1L6.2 3.9H9.5L6.8 5.9 7.7 9 5 7.2 2.3 9 3.2 5.9.5 3.9H3.8L5 1Z"
          fill="var(--accent)" opacity=".5"/>
  </svg>
  ${esc(T.review.aiHint)}
</div>
<div class="rf-actions">
  <button class="rf-skip" data-act="close-review" type="button">${esc(T.review.skip)}</button>
  <div style="flex:1"></div>
  <button class="rf-save" data-act="save-review" type="button">${esc(T.review.save)}</button>
</div>`;
}

function _positionFlyout(flyout: HTMLElement, anchor: HTMLElement): void {
  const rect = anchor.getBoundingClientRect();
  const fw = 320;
  const vw = window.innerWidth;
  const vh = window.innerHeight;

  let left = rect.right + 8;
  if (left + fw > vw - 8) left = rect.left - fw - 8;
  if (left < 8) left = 8;

  let top = rect.top;
  if (top + 300 > vh - 8) top = vh - 308;
  if (top < 8) top = 8;

  flyout.style.cssText = `position:fixed;left:${left}px;top:${top}px;z-index:600;`;
}

function _outsideClick(e: MouseEvent): void {
  const flyout = document.getElementById(FLYOUT_ID);
  if (!flyout) { closeReviewFlyout(); return; }
  if (!flyout.contains(e.target as Node)) {
    closeReviewFlyout();
  }
}

/** appShell 根委托调用此函数处理复盘浮层内的点击 */
export function handleReviewFlyoutClick(act: string): void {
  if (act === "close-review") {
    closeReviewFlyout();
    return;
  }
  if (act === "save-review") {
    const flyout = document.getElementById(FLYOUT_ID);
    if (!flyout || !_currentBlockId) { closeReviewFlyout(); return; }
    const ta = flyout.querySelector<HTMLTextAreaElement>(".rf-textarea");
    const note = ta?.value ?? "";
    saveReviewNote(_currentBlockId, note);
    closeReviewFlyout();
    return;
  }
}

function esc(s: string): string {
  return (s ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!,
  );
}
