/**
 * 数据操作 · CRUD
 *
 * 所有写操作：修改内存 store → 自动 saveStore()
 * 不抛错（除非传入非法 id 严格场景），让 UI 层简单调用
 *
 * M1-New.3R 新增：
 *   - TimeBlock CRUD（含 source / reviewNote 字段）
 *   - updateTaskScheduleStatus（任务排程状态联动）
 *   - Routine Rail actions
 */

import {
  type Priority,
  type BlockStatus,
  type BlockSource,
  type ScheduleStatus,
  type WjbTask,
  type WjbTimeBlock,
  type WjbRoutineState,
  nowIso,
  uid,
  localDateKey,
} from "./types";
import { getStore, saveStore } from "./storage";

/* ============================================================
 * Task CRUD
 * ============================================================ */

/**
 * 快速捕捉：创建一条新任务进收件箱
 *   projectId=null · priority=P3 · status=todo
 */
export function createTask(title: string, overrides: Partial<WjbTask> = {}): WjbTask {
  const now = nowIso();
  const task: WjbTask = {
    id:          uid("task"),
    title:       title.trim(),
    description: "",
    projectId:   null,
    priority:    "P3",
    status:      "todo",
    createdAt:   now,
    updatedAt:   now,
    completedAt: null,
    scheduleStatus: "unscheduled",
    ...overrides,
  };
  const store = getStore();
  store.tasks.unshift(task);
  saveStore();
  return task;
}

/**
 * 编辑任务字段（只允许业务字段；id / createdAt 不可改）
 */
export function updateTask(
  id: string,
  patch: Partial<Omit<WjbTask, "id" | "createdAt">>,
): WjbTask | null {
  const store = getStore();
  const t = store.tasks.find((x) => x.id === id);
  if (!t) return null;
  Object.assign(t, patch);
  t.updatedAt = nowIso();
  saveStore();
  return t;
}

/** 完成任务 */
export function completeTask(id: string): WjbTask | null {
  const now = nowIso();
  return updateTask(id, { status: "done", completedAt: now, scheduleStatus: "done" });
}

/** 取消完成 */
export function uncompleteTask(id: string): WjbTask | null {
  return updateTask(id, { status: "todo", completedAt: null });
}

/**
 * 删除任务（同时移除关联时间块的 taskId 指向，但保留时间块本体）
 */
export function deleteTask(id: string): boolean {
  const store = getStore();
  const idx = store.tasks.findIndex((t) => t.id === id);
  if (idx === -1) return false;
  store.tasks.splice(idx, 1);
  // 解除时间块关联（不删除时间块本身，source 降级为 manual）
  store.timeBlocks.forEach((b) => {
    if (b.taskId === id) {
      b.taskId = null;
      b.source = "manual";
      b.updatedAt = nowIso();
    }
  });
  saveStore();
  return true;
}

/**
 * 更新任务排程状态（根据关联时间块自动计算，或手动传入）
 */
export function updateTaskScheduleStatus(taskId: string): void {
  const store = getStore();
  const task = store.tasks.find((t) => t.id === taskId);
  if (!task || task.status === "done") return;

  const now = Date.now();
  const futureBlocks = store.timeBlocks.filter(
    (b) => b.taskId === taskId && new Date(b.end).getTime() > now,
  );

  let status: ScheduleStatus;
  if (!task.dueDate) {
    status = futureBlocks.length > 0 ? "partial" : "unscheduled";
  } else {
    const today = localDateKey();
    if (task.dueDate < today) {
      status = futureBlocks.length > 0 ? "partial" : "overdue";
    } else {
      status = futureBlocks.length > 0 ? "partial" : "unscheduled";
    }
  }
  task.scheduleStatus = status;
  task.updatedAt = nowIso();
  saveStore();
}

/* ----- 项目查找 ----- */
export function findProject(id: string | null) {
  if (!id) return null;
  return getStore().projects.find((p) => p.id === id) ?? null;
}

/* ----- 任务查找 ----- */
export function findTask(id: string) {
  return getStore().tasks.find((t) => t.id === id) ?? null;
}

/* ----- priority 文案映射 ----- */
const PRI_LABEL: Record<Priority, string> = { P1: "紧急", P2: "高", P3: "中", P4: "低" };
export function priorityLabel(p: Priority): string { return PRI_LABEL[p]; }
export function priorityClass(p: Priority): string { return `is-${p.toLowerCase()}`; }

/* ============================================================
 * TimeBlock CRUD · M1-New.3R
 * ============================================================ */

/**
 * 创建时间块
 * start / end 必须是完整 ISO 8601 字符串（由 UI 层组合本地日期 + HH:MM 生成）
 */
export function createTimeBlock(params: {
  title: string;
  start: string;
  end:   string;
  status?: BlockStatus;
  taskId?: string | null;
  source?: BlockSource;
}): WjbTimeBlock {
  const now = nowIso();
  const source: BlockSource = params.source ?? (params.taskId ? "task" : "manual");
  const block: WjbTimeBlock = {
    id:        uid("tb"),
    title:     params.title.trim(),
    start:     params.start,
    end:       params.end,
    status:    params.status ?? "planned",
    taskId:    params.taskId ?? null,
    source,
    createdAt: now,
    updatedAt: now,
  };
  getStore().timeBlocks.push(block);
  saveStore();
  // 联动更新任务排程状态
  if (params.taskId) updateTaskScheduleStatus(params.taskId);
  return block;
}

/**
 * 编辑时间块（id / createdAt 不可改）
 */
export function updateTimeBlock(
  id: string,
  patch: Partial<Omit<WjbTimeBlock, "id" | "createdAt">>,
): WjbTimeBlock | null {
  const store = getStore();
  const b = store.timeBlocks.find((x) => x.id === id);
  if (!b) return null;
  const oldTaskId = b.taskId;
  Object.assign(b, patch);
  b.updatedAt = nowIso();
  saveStore();
  // 联动更新任务排程状态
  if (oldTaskId) updateTaskScheduleStatus(oldTaskId);
  if (patch.taskId && patch.taskId !== oldTaskId) updateTaskScheduleStatus(patch.taskId);
  return b;
}

/**
 * 删除时间块（不删除关联任务）
 */
export function deleteTimeBlock(id: string): boolean {
  const store = getStore();
  const idx = store.timeBlocks.findIndex((b) => b.id === id);
  if (idx === -1) return false;
  const taskId = store.timeBlocks[idx].taskId;
  store.timeBlocks.splice(idx, 1);
  saveStore();
  if (taskId) updateTaskScheduleStatus(taskId);
  return true;
}

/** 查找时间块 */
export function findTimeBlock(id: string): WjbTimeBlock | null {
  return getStore().timeBlocks.find((b) => b.id === id) ?? null;
}

/** 关联任务 */
export function linkTimeBlockTask(blockId: string, taskId: string): WjbTimeBlock | null {
  const block = findTimeBlock(blockId);
  if (!block) return null;
  // 获取任务标题用于更新时间块 title（如果时间块标题还是默认值）
  const task = findTask(taskId);
  const patch: Partial<WjbTimeBlock> = { taskId, source: "task" };
  if (task && (!block.title || block.title === "新时间块")) {
    patch.title = task.title;
  }
  return updateTimeBlock(blockId, patch);
}

/** 取消关联任务（时间块降级为 manual） */
export function unlinkTimeBlockTask(blockId: string): WjbTimeBlock | null {
  return updateTimeBlock(blockId, { taskId: null, source: "manual" });
}

/** 更新时间块状态（planned → running → done） */
export function setTimeBlockStatus(id: string, status: BlockStatus): WjbTimeBlock | null {
  return updateTimeBlock(id, { status });
}

/** 保存复盘笔记 */
export function saveReviewNote(id: string, note: string): WjbTimeBlock | null {
  return updateTimeBlock(id, { reviewNote: note });
}

/* ============================================================
 * Routine Rail · M1-New.3
 * ============================================================ */

/**
 * 获取今日 routineState，如不存在或日期不同则重置初始化
 * （次日访问自动重置所有 checks 为 false）
 */
export function getOrInitRoutineState(): WjbRoutineState {
  const store = getStore();
  const today = localDateKey();
  if (
    !store.routineState ||
    typeof store.routineState !== "object" ||
    store.routineState.date !== today
  ) {
    store.routineState = { date: today, checks: {} };
    saveStore();
  }
  return store.routineState;
}

/**
 * 切换 routine item 勾选状态，返回新状态
 */
export function toggleRoutineCheck(key: string): boolean {
  const state = getOrInitRoutineState();
  state.checks[key] = !state.checks[key];
  saveStore();
  return !!state.checks[key];
}
