/**
 * localStorage 读写 · 单一真理源
 *
 * key:           wuxianjinbu-data-v1
 * schemaVersion: wuxianjinbu-v1
 *
 * 严格不读 cadence-data-lishan-v4 或任何旧 key。
 * 不做旧数据迁移（后置）。
 * schemaVersion 不匹配 / 解析失败 / 结构损坏 → fallback 到 seed，并在内存留 fallback 标记
 *   供设置面板提示。
 */

import {
  type WjbDataStore,
  STORAGE_KEY,
  SCHEMA_VERSION,
  nowIso,
} from "./types";
import { buildDefaultSeed } from "./seed";

let _store:           WjbDataStore | null = null;
let _fallbackReason:  string | null = null;

export function loadStore(): WjbDataStore {
  if (_store) return _store;

  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      _store = buildDefaultSeed();
      saveStore();
      return _store;
    }
    const parsed = JSON.parse(raw) as unknown;
    if (!isValidStore(parsed)) {
      _fallbackReason = "数据结构异常，已恢复为默认种子";
      _store = buildDefaultSeed();
      // 不覆盖 localStorage，让用户决定 reset 或导出后清理
      return _store;
    }
    _store = parsed as WjbDataStore;
    return _store;
  } catch (err) {
    _fallbackReason = "本地数据解析失败，已恢复为默认种子";
    _store = buildDefaultSeed();
    return _store;
  }
}

export function saveStore(): void {
  if (!_store) return;
  _store.meta.updatedAt = nowIso();
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(_store));
  } catch (err) {
    console.warn("[wuxianjinbu] saveStore 失败", err);
  }
}

export function resetStore(): WjbDataStore {
  _store = buildDefaultSeed();
  _fallbackReason = null;
  saveStore();
  return _store;
}

export function exportStore(): string {
  return JSON.stringify(loadStore(), null, 2);
}

export function getStore(): WjbDataStore {
  return loadStore();
}

export function getFallbackReason(): string | null {
  return _fallbackReason;
}

/* ----- 验证（修复 #3 · M1-New.2 P1：深度校验）-----
 *
 * 旧版只看顶层字段存在性 → 任何坏 priority / 坏 status / 坏 colorToken / 缺核心字段
 *   都能存进 store 引起渲染崩。
 * 新版逐对象逐核心字段校验；任一失败 → 全量 fallback seed + 提示。
 */

const VALID_PRIORITIES   = new Set(["P1", "P2", "P3", "P4"]);
const VALID_TASK_STATUS  = new Set(["todo", "done"]);
const VALID_BLOCK_STATUS = new Set(["planned", "running", "done"]);
const VALID_PROJECT_TOKEN = new Set(["--project-1", "--project-2", "--project-3", "--project-4"]);

function nonEmptyStr(v: unknown): v is string {
  return typeof v === "string" && v.length > 0;
}

function isValidTask(t: unknown): boolean {
  if (!t || typeof t !== "object") return false;
  const x = t as Record<string, unknown>;
  if (!nonEmptyStr(x.id)) return false;
  if (typeof x.title !== "string") return false;
  if (x.projectId !== null && !nonEmptyStr(x.projectId)) return false;
  if (typeof x.priority !== "string" || !VALID_PRIORITIES.has(x.priority)) return false;
  if (typeof x.status !== "string" || !VALID_TASK_STATUS.has(x.status)) return false;
  if (!nonEmptyStr(x.createdAt)) return false;
  if (!nonEmptyStr(x.updatedAt)) return false;
  // dueDate 可选；completedAt 可选 null/string
  if (x.dueDate !== undefined && typeof x.dueDate !== "string") return false;
  if (x.completedAt !== undefined && x.completedAt !== null && typeof x.completedAt !== "string") return false;
  return true;
}

function isValidProject(p: unknown): boolean {
  if (!p || typeof p !== "object") return false;
  const x = p as Record<string, unknown>;
  if (!nonEmptyStr(x.id)) return false;
  if (!nonEmptyStr(x.name)) return false;
  if (typeof x.colorToken !== "string" || !VALID_PROJECT_TOKEN.has(x.colorToken)) return false;
  if (!nonEmptyStr(x.createdAt)) return false;
  if (!nonEmptyStr(x.updatedAt)) return false;
  return true;
}

function isValidBlock(b: unknown): boolean {
  if (!b || typeof b !== "object") return false;
  const x = b as Record<string, unknown>;
  if (!nonEmptyStr(x.id)) return false;
  if (typeof x.title !== "string") return false;
  if (x.taskId !== undefined && x.taskId !== null && !nonEmptyStr(x.taskId)) return false;
  if (!nonEmptyStr(x.start)) return false;
  if (!nonEmptyStr(x.end)) return false;
  if (typeof x.status !== "string" || !VALID_BLOCK_STATUS.has(x.status)) return false;
  if (!nonEmptyStr(x.createdAt)) return false;
  if (!nonEmptyStr(x.updatedAt)) return false;
  return true;
}

function isValidSettings(s: unknown): boolean {
  if (!s || typeof s !== "object") return false;
  const x = s as Record<string, unknown>;
  return x.firstDayOfWeek === "monday" || x.firstDayOfWeek === "sunday";
}

function isValidMeta(m: unknown): boolean {
  if (!m || typeof m !== "object") return false;
  const x = m as Record<string, unknown>;
  return nonEmptyStr(x.createdAt) && nonEmptyStr(x.updatedAt);
}

function isValidStore(x: unknown): x is WjbDataStore {
  if (!x || typeof x !== "object") return false;
  const s = x as Partial<WjbDataStore>;
  if (s.schemaVersion !== SCHEMA_VERSION) return false;
  if (!Array.isArray(s.tasks)      || !s.tasks.every(isValidTask))         return false;
  if (!Array.isArray(s.projects)   || !s.projects.every(isValidProject))   return false;
  if (!Array.isArray(s.timeBlocks) || !s.timeBlocks.every(isValidBlock))   return false;
  if (!isValidSettings(s.settings)) return false;
  if (!isValidMeta(s.meta))         return false;
  return true;
}
