/**
 * 派生数据 selectors
 * 组件层只查 selectors，不直接遍历 store；改 schema 时只动这里
 *
 * M1-New.3R 更新：
 *   - todayBlocks 改为重叠判断（不再按 start 日期严格等于今天）
 *   - 新增 blocksForDay / runningBlockForDay
 *   - 新增任务池筛选 selectors
 *   - 今日进度改为时间块完成数/总数
 */

import { type WjbTask, type WjbTimeBlock, type WjbDataStore, localDateKey } from "./types";
import { getStore } from "./storage";
import { blockOverlapsDay } from "../lib/timeUtils";

// 修复 #2：用本地时区计算"今天"，避免 toISOString UTC slice 在夜间跨日
function todayDate(): string { return localDateKey(); }

/* ─── 收件箱 ─── */
export function isInboxTask(t: WjbTask): boolean {
  return t.status !== "done" && t.projectId === null;
}
export function inboxTasks(): WjbTask[] {
  return getStore().tasks.filter(isInboxTask);
}
export function inboxCount(): number {
  return inboxTasks().length;
}

/* ─── 即将到来 ─── */
export function upcomingTasks(): WjbTask[] {
  const t = todayDate();
  return getStore().tasks.filter(
    (x) => x.status !== "done" && !!x.dueDate && x.dueDate >= t,
  );
}
export function upcomingCount(): number {
  return upcomingTasks().length;
}

/* ─── 全部未完成 ─── */
export function allActiveTasks(): WjbTask[] {
  return getStore().tasks.filter((t) => t.status !== "done");
}
export function allActiveCount(): number {
  return allActiveTasks().length;
}

/* ─── 已完成 ─── */
export function doneTasks(): WjbTask[] {
  return getStore().tasks.filter((t) => t.status === "done");
}
export function doneCount(): number {
  return doneTasks().length;
}

/* ─── 项目下任务数 ─── */
export function projectTaskCount(projectId: string): number {
  return getStore().tasks.filter((t) => t.projectId === projectId && t.status !== "done").length;
}

/* ─── 今日聚焦 / 高优 ─── */
export function priorityTasks(limit = 3): WjbTask[] {
  return getStore().tasks
    .filter((t) => t.status !== "done" && (t.priority === "P1" || t.priority === "P2"))
    .sort((a, b) => (a.priority < b.priority ? -1 : 1))
    .slice(0, limit);
}
export function todayFocus(limit = 2): WjbTask[] {
  const t = todayDate();
  const dueToday = getStore().tasks.filter((x) => x.status !== "done" && x.dueDate === t);
  return dueToday
    .sort((a, b) => (a.priority < b.priority ? -1 : 1))
    .slice(0, limit);
}

/* ─── 时间块（按指定日期，重叠判断）─── */

/**
 * 获取某天的时间块（新版：重叠判断）
 * block.start < dayEnd && block.end > dayStart
 */
export function blocksForDay(dateKey: string): WjbTimeBlock[] {
  return getStore().timeBlocks.filter((b) => blockOverlapsDay(b.start, b.end, dateKey));
}

/**
 * 今日时间块（shortcut）
 */
export function todayBlocks(): WjbTimeBlock[] {
  return blocksForDay(todayDate());
}

/**
 * 获取某天当前进行中的时间块（第一个）
 */
export function runningBlockForDay(dateKey: string): WjbTimeBlock | null {
  return (
    getStore().timeBlocks.find(
      (b) => b.status === "running" && blockOverlapsDay(b.start, b.end, dateKey),
    ) ?? null
  );
}

/** 全局运行中时间块（兼容旧用法） */
export function runningBlock(): WjbTimeBlock | null {
  return getStore().timeBlocks.find((b) => b.status === "running") ?? null;
}

/* ─── 进度（今日：时间块完成/总数）─── */
export function todayProgress(dateKey?: string): { done: number; total: number; pct: number } {
  const key = dateKey ?? todayDate();
  const blocks = blocksForDay(key);
  const done = blocks.filter((b) => b.status === "done").length;
  const total = blocks.length;
  const pct = total === 0 ? 0 : Math.round((done / total) * 100);
  return { done, total, pct };
}

/* ─── 任务池筛选（M1-New.3R）─── */

/** 某任务是否有未来时间块（当前时刻之后） */
function hasFutureBlock(taskId: string): boolean {
  const now = Date.now();
  return getStore().timeBlocks.some(
    (b) => b.taskId === taskId && new Date(b.end).getTime() > now,
  );
}

/** 今日应处理：dueDate=今天 OR 逾期未完成 */
export function poolTodayTasks(): WjbTask[] {
  const t = todayDate();
  return getStore().tasks.filter(
    (x) =>
      x.status !== "done" &&
      (x.dueDate === t || (!!x.dueDate && x.dueDate < t)),
  );
}

/** 高优先级：P1 或 P2，未完成 */
export function poolHighPriorityTasks(): WjbTask[] {
  return getStore().tasks.filter(
    (x) => x.status !== "done" && (x.priority === "P1" || x.priority === "P2"),
  );
}

/** 即将到期：dueDate 在未来 7 天内，未完成 */
export function poolUpcomingDeadlineTasks(): WjbTask[] {
  const t = todayDate();
  const [ty, tm, td] = t.split("-").map(Number);
  const limit = new Date(ty, tm - 1, td + 7);
  const limitKey = `${limit.getFullYear()}-${String(limit.getMonth() + 1).padStart(2, "0")}-${String(limit.getDate()).padStart(2, "0")}`;
  return getStore().tasks.filter(
    (x) => x.status !== "done" && !!x.dueDate && x.dueDate >= t && x.dueDate <= limitKey,
  );
}

/** 未排入：未完成且没有未来时间块 */
export function poolUnscheduledTasks(): WjbTask[] {
  return getStore().tasks.filter(
    (x) => x.status !== "done" && !hasFutureBlock(x.id),
  );
}

/** 已部分安排：有未来时间块但任务未完成 */
export function poolPartialTasks(): WjbTask[] {
  return getStore().tasks.filter(
    (x) => x.status !== "done" && hasFutureBlock(x.id),
  );
}

/** 逾期未安排：dueDate < 今天，未完成，无未来时间块 */
export function poolOverdueTasks(): WjbTask[] {
  const t = todayDate();
  return getStore().tasks.filter(
    (x) =>
      x.status !== "done" &&
      !!x.dueDate &&
      x.dueDate < t &&
      !hasFutureBlock(x.id),
  );
}

/* ─── 工具：拿原始 store（设置面板用）─── */
export function storeSnapshot(): WjbDataStore { return getStore(); }
